});

arrowOptions:AddLabel("Skin"):AddDropdown({
	Default = "Triangle",
	Values = { "Triangle", "Triangle 2", "Triangle 3", "Arrows", "Arrow 3", "White", "Arrow",
		"Arrows 3", "12213", "Arr", "GPS", "Arrow Glow" },
	Flag = "esp_arrow_skin",
