	});

	Sections.FunJump:AddLabel("Walk Mode"):AddDropdown({
		Name = "Walk Mode",
		Default = "WalkSpeed",
		Values = { "WalkSpeed", "CFrame" },
		Flag = "fun_walk_mode",
		ToolTip = "WalkSpeed: edits the humanoid. CFrame: moves you each frame, past game speed locks",
		Callback = function(v) walk_mode = v == "CFrame" and "CFrame" or "WalkSpeed" end,
	});

	Sections.FunJump:AddLabel("Jump Power"):AddToggle({
		Name = "Jump Power",
		Default = false,
		Flag = "fun_jump_on",
		Callback = function(v)
			jp_on = v

			if v then capture_move() else release_jump() end
		end,
	});

	Sections.FunJump:AddLabel("Jump Height"):AddSlider({
		Name = "Jump Height",
		Min = 50, Max = 200, Default = 80, Rounding = 0, Size = 110,
		Flag = "fun_jump_value",
		Callback = function(v) jp_value = v end,
	});

	Sections.FunJump:AddLabel("Bunny Hop"):AddToggle({
		Name = "Bunny Hop",
		Default = false,
		Flag = "fun_bhop",
		ToolTip = "Jumps the moment you land",
		Callback = function(v) bhop_on = v end,
	});

	Sections.FunJump:AddLabel("Sprint"):AddToggle({
		Name = "Sprint",
		Default = false,
		Flag = "fun_sprint",
		ToolTip = "Hold Left Shift to dash",
		Callback = function(v)
			sprint_on = v

			if not v and sprint_held then
				sprint_held = false

				local hum = get_hum()

				if hum and not ws_on and sprint_prev ~= nil then hum.WalkSpeed = sprint_prev end

				sprint_prev = nil
			end
		end,
	});

	Sections.FunJump:AddLabel("Sprint Speed"):AddSlider({
		Name = "Sprint Speed",
		Min = 20, Max = 300, Default = 60, Rounding = 0, Size = 110,
		Flag = "fun_sprint_speed",
		Callback = function(v) sprint_speed = v end,
	});

	ESP.ClearMisc = onUnload("misc", function()
		anti_afk, anti_fling, anti_void, anti_trap = false, false, false, false
		coin_on, fade_on = false, false
		noclip_on, fly_on = false, false
		inf_jump_on, wallhop_on = false, false
		ws_on, jp_on = false, false
		bhop_on, sprint_on, sprint_held = false, false, false
		sprint_prev = nil

		pcall(function() ws.FallenPartsDestroyHeight = void_original end)

		for _, conn in ipairs({ idle_conn, coin_conn, coin_desc_conn, step_conn, fling_beat_conn, speed_conn, jump_conn, fly_conn, move_conn }) do
			pcall(function() conn:Disconnect() end)
		end

		if fade_desc_conn then pcall(function() fade_desc_conn:Disconnect() end) fade_desc_conn = nil end

		pcall(trap_detach)
		pcall(restore_coins)
		pcall(fade_restore)
		pcall(fling_restore)
		pcall(noclip_restore)
		pcall(release_part_index)

		local hum = get_hum()

		if hum then
			pcall(function()
				if ws_original then hum.WalkSpeed = ws_original end
				if jp_original then hum.JumpPower = jp_original end
				if use_jp_original ~= nil then hum.UseJumpPower = use_jp_original end
			end)
		end
	end);
end);

guard("fun hud", function()
	local th = NeverLose.Lib.theme;

	local wantFps, wantPing, shotMode = false, false, false;
	local shotPinned = false;
	local pill, label;
	local frames, span = 0, 0;
	local hidden = {};
	local sweepAt = 0;
	local hideUntil = 0;

	local function isMine(gui)
		if typeof(gui) ~= "Instance" then return false end;
		if gui == NeverLose.ScreenGui then return true end;

		local scr = NeverLose.ScreenGui;

		return typeof(scr) == "Instance" and scr:IsDescendantOf(gui);
	end;

	local function screenGuis()
		local list = {};
		local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui");

		if playerGui then
			for _, gui in ipairs(playerGui:GetChildren()) do
				if gui:IsA("ScreenGui") and not isMine(gui) then
					list[#list + 1] = gui;
				end;
			end;
		end;

		local ok, coreGui = pcall(function() return game:GetService("CoreGui") end);

		if ok and typeof(coreGui) == "Instance" then
			for _, gui in ipairs(coreGui:GetChildren()) do
				if gui:IsA("ScreenGui") and not isMine(gui) then
					list[#list + 1] = gui;
				end;
			end;
		end;

		return list;
	end;

	local function ensure()
		if pill and pill.Parent then return end;

		pill = Instance.new("Frame");
		pill.Name = NeverLose.RandomString();
		pill.AnchorPoint = Vector2.new(1, 1);
		pill.Position = UDim2.new(1, -14, 1, -14);
		pill.Size = UDim2.fromOffset(0, 26);
		pill.AutomaticSize = Enum.AutomaticSize.X;
		pill.BackgroundColor3 = th.panel;
		pill.BorderSizePixel = 0;
		pill.Visible = false;
		pill.ZIndex = 905;
		pill.Parent = NeverLose.ScreenGui;

		Instance.new("UICorner", pill).CornerRadius = UDim.new(1, 0);

		local edge = Instance.new("UIStroke");
		edge.Color = th.line;
		edge.Transparency = 0.4;
		edge.Parent = pill;

		local pad = Instance.new("UIPadding");
		pad.PaddingLeft = UDim.new(0, 12);
		pad.PaddingRight = UDim.new(0, 12);
		pad.Parent = pill;

		label = Instance.new("TextLabel");
		label.BackgroundTransparency = 1;
		label.Size = UDim2.fromOffset(0, 20);
		label.AutomaticSize = Enum.AutomaticSize.X;
		label.Font = Enum.Font.GothamBold;
		label.TextSize = 12;
		label.TextColor3 = th.text;
		label.Text = "";
		label.ZIndex = 906;
		label.Parent = pill;
	end;

	local stats = game:GetService("Stats");
	local pingItem;

	local function pingText()
		if not pingItem then
			local ok, item = pcall(function()
				return stats.Network.ServerStatsItem["Data Ping"];
			end);

			if ok then pingItem = item end;
		end;

		if not pingItem then return nil end;

		local ok, value = pcall(function() return pingItem:GetValueString() end);

		if ok and type(value) == "string" and value ~= "" then return value end;

		return nil;
	end;

	local function sweep()
		for _, gui in ipairs(screenGuis()) do
			if gui.Visible then
				hidden[#hidden + 1] = gui;
				gui.Visible = false;
			end;
		end;
	end;

	local function restoreShot()
		for _, gui in ipairs(hidden) do
			if gui.Parent then pcall(function() gui.Visible = true end) end;
		end;

		table.clear(hidden);
	end;

	local function refresh()
		ensure();
		pill.Visible = wantFps or wantPing;
	end;

	NeverLose:AddSignal(RunService.Heartbeat:Connect(function(dt)
		if not (wantFps or wantPing or shotMode) then return end;

		if hideUntil > 0 and os.clock() >= hideUntil then
			hideUntil = 0;

			if not shotPinned then
				shotMode = false;
				restoreShot();
			end;
		end;

		frames = frames + 1;
		span = span + dt;

		if span >= 0.25 then
			if shotMode and os.clock() >= sweepAt then
				sweepAt = os.clock() + 0.2;
				sweep();
			end;

			if wantFps or wantPing then
				local parts = {};

				if wantFps then parts[#parts + 1] = "FPS " .. math.floor(frames / span + 0.5) end;

				if wantPing then
					local ping = pingText();

					if ping then parts[#parts + 1] = "Ping " .. ping end;
				end;

				ensure();
				label.Text = table.concat(parts, "    ");
				pill.Visible = true;
			end;

			frames, span = 0, 0;
		end;
	end));

	Sections.FunHud:AddLabel("FPS Counter"):AddToggle({
		Default = false, Flag = "fun_fps",
		Callback = function(v)
			wantFps = v;
			refresh();
		end,
	});

	Sections.FunHud:AddLabel("Ping Counter"):AddToggle({
		Default = false, Flag = "fun_ping",
		Callback = function(v)
			wantPing = v;
			refresh();
		end,
	});

	Sections.FunShot:AddLabel("Screenshot Mode"):AddToggle({
		Default = false, Flag = "fun_screenshot",
		ToolTip = "Hides every other GUI for a clean screenshot",
		Callback = function(v)
			shotMode = v and true or false;
			shotPinned = shotMode;
			hideUntil = 0;

			if not shotMode then restoreShot() end;
		end,
	});

	Sections.FunShot:AddButton({
		Name = "Hide UI (5s)",
		Icon = "video",
		Callback = function()
			shotMode = true;
			sweepAt = 0;
			hideUntil = os.clock() + 5;
		end,
	});

	onUnload("fun hud", function()
		shotMode = false;
		shotPinned = false;
		hideUntil = 0;
		restoreShot();

		if pill then
			pill:Destroy();
			pill, label = nil, nil;
		end;
	end);
end);

guard("aimbot", function()
	local A = {
		On = false, Key = "E", RightMouse = true, Mode = "Hold", Method = "Camera", TurnCamera = true,
		Fov = 220, Smooth = 3, Part = "Head", Priority = "Crosshair",
		Visible = true, Range = 0,
		TeamCheck = true, IgnoreFriends = false,
		Bots = false, BotsOnly = false,
		Trigger = false, TriggerDelay = 150,
		Circle = true, DynamicCircle = false, CircleColor = Color3.fromRGB(255, 84, 84), CircleFilled = false,
	};

	ESP.Aimbot = A;

	local uis = game:GetService("UserInputService");
	local AIM_STEP = "NeverLoseAimbot";
	local PARTS = { "Head", "UpperTorso", "Torso", "HumanoidRootPart" };

	local circle, stepConn = nil, nil;
	local lastShot = 0;
	local alive = true;

	local function ensureCircle()
		if circle then return circle end;

		local ok, drawn = pcall(function() return Drawing.new("Circle") end);

		if not ok or not drawn then return nil end;

		drawn.Thickness = 1.5;
		drawn.NumSides = 96;
		drawn.Filled = false;
		drawn.Visible = false;
		drawn.Radius = A.Fov;

		circle = drawn;

		return circle;
	end;

	local aimToggled = false;

	local function keyDown()
		if A.Key and A.Key ~= "" then
			local ok, key = pcall(function() return Enum.KeyCode[A.Key] end);

			if ok and key and uis:IsKeyDown(key) then return true end;
		end;

		return A.RightMouse and uis:IsMouseButtonPressed(Enum.UserInputType.MouseButton2);
	end;

	local function active()
		if A.Mode == "Toggle" then
			return aimToggled or (A.RightMouse and uis:IsMouseButtonPressed(Enum.UserInputType.MouseButton2));
		end;

		return keyDown();
	end;

	NeverLose:AddSignal(uis.InputBegan:Connect(function(input, processed)
		if processed or A.Mode ~= "Toggle" or not (A.On or A.Trigger) then return end;

		if input.UserInputType ~= Enum.UserInputType.Keyboard or not A.Key or A.Key == "" then return end;

		local ok, key = pcall(function() return Enum.KeyCode[A.Key] end);

		if ok and key and input.KeyCode == key then aimToggled = not aimToggled end;
	end));

	local friendCache = {};

	local function isTeammate(player)
		if player == LocalPlayer then return false end;

		local mine, theirs = LocalPlayer.Team, player.Team;

		if mine and theirs and mine == theirs then return true end;

		if LocalPlayer.TeamColor and player.TeamColor
			and LocalPlayer.TeamColor == player.TeamColor
			and LocalPlayer.Neutral == false and player.Neutral == false then
			return true;
		end;

		return false;
	end;

	local function isFriend(player)
		if player == LocalPlayer then return false end;

		local cached = friendCache[player.UserId];

		if cached ~= nil then return cached end;

		friendCache[player.UserId] = false;

		task.spawn(function()
			local ok, result = pcall(function() return LocalPlayer:IsFriendsWith(player.UserId) end);

			friendCache[player.UserId] = (ok and result == true) or false;
		end);

		return false;
	end;

	local function botHolder()
		local highlight = workspace:FindFirstChild("Highlight");
		local enemy = highlight and highlight:FindFirstChild("Enemy");

		return enemy and enemy:FindFirstChild("HighlightHolder") or nil;
	end;

	local function botParts(bot)
		local list = {};

		if not (bot and bot.Parent) then return list end;

		local collider = bot:FindFirstChild("Collider");
		local head = collider and collider:FindFirstChild("Head");

		if not (head and head:IsA("BasePart")) then head = bot:FindFirstChild("Head", true) end;
		if not head then head = bot:FindFirstChildWhichIsA("BasePart", true) end;

		if head and head:IsA("BasePart") then list[#list + 1] = head end;

		if A.Part ~= "Head" and #list > 0 then
			local body;

			if collider then
				body = collider:IsA("BasePart") and collider or collider:FindFirstChildWhichIsA("BasePart");
			end;

			if not body then body = bot:FindFirstChildWhichIsA("BasePart", true) end;

			if body and body ~= head and body:IsA("BasePart") then list[#list + 1] = body end;
		end;

		return list;
	end;

	local function botHealth(bot)
		local human = bot:FindFirstChildWhichIsA("Humanoid");

		return human and human.Health or math.huge;
	end;

	local function aimParts(character)
		local list = {};

		if A.Part == "Closest" then
			for _, name in ipairs(PARTS) do
				local part = character:FindFirstChild(name);

				if part then list[#list + 1] = part end;
			end;
		else
			local name = A.Part == "Upper Torso" and "UpperTorso"
				or A.Part == "Lower Torso" and "LowerTorso"
				or A.Part == "HumanoidRootPart" and "HumanoidRootPart"
				or "Head";
			local part = character:FindFirstChild(name) or character:FindFirstChild("Head");

			if part then list[1] = part end;
		end;

		return list;
	end;

	local function pick(camera, center)
		local best, bestPoint, bestScore = nil, nil, nil;
		local origin = camera.CFrame.Position;

		local function scan(part, distance, health)
			if not (part and part.Parent) then return end;

			local at, onScreen = camera:WorldToViewportPoint(part.Position);

			if not onScreen or at.Z <= 0 then return end;

			local span = (Vector2.new(at.X, at.Y) - center).Magnitude;

			if span > A.Fov then return end;

			local score = A.Priority == "Closest" and distance
				or A.Priority == "Health" and health
				or span;

			if not bestScore or score < bestScore then
				best, bestPoint, bestScore = part, part.Position, score;
			end;
		end;

		if not A.BotsOnly then
			for _, player in ipairs(Players:GetPlayers()) do
				if player ~= LocalPlayer
					and not (A.TeamCheck and isTeammate(player))
					and not (A.IgnoreFriends and isFriend(player)) then

					local character = player.Character;
					local root = character and character:FindFirstChild("HumanoidRootPart");
					local human = character and character:FindFirstChildWhichIsA("Humanoid");

					if root and human and human.Health > 0 then
						local distance = (root.Position - origin).Magnitude;

						if A.Range <= 0 or distance <= A.Range then
							if not A.Visible or ESP.Visibility.Character(camera, character, root) then
								for _, part in ipairs(aimParts(character)) do
									scan(part, distance, human.Health);
								end;
							end;
						end;
					end;
				end;
			end;
		end;

		if A.Bots then
			local holder = botHolder();

			if holder then
				for _, bot in ipairs(holder:GetChildren()) do
					local parts = botParts(bot);

					if #parts > 0 then
						local head = parts[1];
						local distance = (head.Position - origin).Magnitude;

						if (A.Range <= 0 or distance <= A.Range)
							and (not A.Visible or ESP.Visibility.Character(camera, bot, head)) then
							local health = botHealth(bot);

							for _, part in ipairs(parts) do
								scan(part, distance, health);
							end;
						end;
					end;
				end;
			end;
		end;

		return best, bestPoint, bestScore;
	end;

	local mouse = LocalPlayer:GetMouse();

	local mouseRel = nil;
	local vim = nil;

	if type(mousemoverel) == "function" then
		mouseRel = mousemoverel;
	elseif type(getgenv) == "function" then
		local ok, env = pcall(getgenv);

		if ok and type(env) == "table" and type(env.mousemoverel) == "function" then
			mouseRel = env.mousemoverel;
		end;
	end;

	pcall(function() vim = game:GetService("VirtualInputManager") end);

	local vimCursor = nil;

	local function moveMouse(dx, dy)
		if mouseRel then return pcall(mouseRel, dx, dy) end;
		if not vim then return false end;

		local raw = Vector2.new(mouse.X, mouse.Y);

		if not vimCursor or (raw - vimCursor).Magnitude > 60 then vimCursor = raw end;

		vimCursor = vimCursor + Vector2.new(dx, dy);

		pcall(function() vim:SendMouseMoveEvent(vimCursor.X, vimCursor.Y, game) end);

		return true;
	end;

	local function aimMouse(camera, position)
		local at = camera:WorldToViewportPoint(position);

		if not at or at.Z <= 0 then return end;

		local gain = 1 / math.max(1, A.Smooth);

		moveMouse((at.X - mouse.X) * gain, (at.Y - mouse.Y) * gain);
	end;

	local function aim(camera, position)
		local viaMouse = A.Method == "Mouse" and (mouseRel or vim);

		if viaMouse then aimMouse(camera, position) end;

		if viaMouse and not A.TurnCamera then return end;

		local alpha = 1 / math.max(1, A.Smooth);
		local desired = CFrame.lookAt(camera.CFrame.Position, position);

		camera.CFrame = camera.CFrame:Lerp(desired, alpha);
	end;

	local function fire()
		local now = os.clock();

		if now - lastShot < (A.TriggerDelay / 1000) then return end;

		local character = LocalPlayer.Character;
		local tool = character and character:FindFirstChildOfClass("Tool");

		if not tool then return end;

		local name = string.lower(tool.Name);
		local gun = tool:FindFirstChild("GunClient") or tool:FindFirstChild("KnifeClient")
			or string.find(name, "gun", 1, true) or string.find(name, "revolver", 1, true)
			or string.find(name, "knife", 1, true) or string.find(name, "blade", 1, true);

		if not gun then return end;

		lastShot = now;

		pcall(function() tool:Activate() end);
	end;

	local function step()
		local camera = workspace.CurrentCamera;

		if not camera then
			if circle then circle.Visible = false end;

			return;
		end;

		local size = camera.ViewportSize;
		local center = Vector2.new(size.X * 0.5, size.Y * 0.5);
		local enabled = A.On or A.Trigger;
		local position = nil;

		if enabled then
			local character = LocalPlayer.Character;
			local human = character and character:FindFirstChildWhichIsA("Humanoid");

			if human and human.Health > 0 and active() then
				local _, found = pick(camera, center);

				position = found;
			end;
		end;

		if A.Circle and enabled then
			local drawn = ensureCircle();

			if drawn then
				local colour = A.CircleColor;

				if A.DynamicCircle then
					colour = position and A.CircleColor or Color3.new(1, 1, 1);
				end;

				drawn.Position = center;
				drawn.Radius = A.Fov;
				drawn.Color = colour;
				drawn.Filled = A.CircleFilled;
				drawn.Visible = true;
			end;
		elseif circle then
			circle.Visible = false;
		end;

		if not enabled then
			aimToggled = false;

			return;
		end;

		if not position then return end;

		if A.On then aim(camera, position) end;
		if A.Trigger then fire() end;
	end;

	local bound = pcall(function()
		RunService:BindToRenderStep(AIM_STEP, Enum.RenderPriority.Camera.Value + 1, step);
	end);

	if not bound then
		stepConn = RunService.RenderStepped:Connect(step);
	end;

	Sections.Aimbot:AddLabel("Aimbot"):AddToggle({
		Default = false, Flag = "aim_on",
		ToolTip = "Hold the aim key to lock onto targets",
		Callback = function(v) A.On = v end,
	});

	Sections.Aimbot:AddLabel("Aim Key"):AddKeybind({
		Default = "E", Flag = "aim_key",
		Callback = function(v) A.Key = v end,
	});

	Sections.Aimbot:AddLabel("Aim Mode"):AddDropdown({
		Default = "Hold",
		Values = { "Hold", "Toggle" },
		Flag = "aim_mode",
		ToolTip = "Hold: aim while the key is down. Toggle: press once to aim",
		Callback = function(v)
			A.Mode = v == "Toggle" and "Toggle" or "Hold";
			aimToggled = false;
		end,
	});

	Sections.Aimbot:AddLabel("Aim Method"):AddDropdown({
		Default = "Camera",
		Values = { "Camera", "Mouse" },
		Flag = "aim_method",
		ToolTip = "Camera: turns your view onto the target. Mouse: moves the cursor onto the target (works best with right mouse or shift lock)",
		Callback = function(v)
			A.Method = v == "Mouse" and "Mouse" or "Camera";

			if A.Method == "Mouse" and not mouseRel and not vim then
				Notification.new({
					Title = "Aimbot",
					Content = "no mouse control available - using camera",
					Duration = 4,
				});
			end;
		end,
	});

	Sections.Aimbot:AddLabel("Turn Camera"):AddToggle({
		Default = true, Flag = "aim_turn_cam",
		ToolTip = "Mouse method: also rotate the view onto the target while the cursor locks to it",
		Callback = function(v) A.TurnCamera = v end,
	});

	Sections.Aimbot:AddLabel("Right Mouse"):AddToggle({
		Default = true, Flag = "aim_rmb",
		ToolTip = "Also aim while holding right mouse",
		Callback = function(v) A.RightMouse = v end,
	});

	Sections.Aimbot:AddLabel("Smoothness"):AddSlider({
		Min = 1, Max = 20, Default = 3, Rounding = 0, Size = 90,
		Flag = "aim_smooth",
		Callback = function(v) A.Smooth = v end,
	});

	Sections.Aimbot:AddLabel("Target Part"):AddDropdown({
		Default = "Head",
		Values = { "Head", "Upper Torso", "Lower Torso", "HumanoidRootPart", "Closest" },
		Flag = "aim_part",
		Callback = function(v) A.Part = v end,
	});

	Sections.AimTarget:AddLabel("Team Check"):AddToggle({
		Default = true, Flag = "aim_team",
		ToolTip = "Skip players on your team",
		Callback = function(v) A.TeamCheck = v end,
	});

	Sections.AimTarget:AddLabel("Ignore Friends"):AddToggle({
		Default = false, Flag = "aim_friends",
		ToolTip = "Skip players on your Roblox friends list",
		Callback = function(v) A.IgnoreFriends = v end,
	});

	Sections.AimTarget:AddLabel("Priority"):AddDropdown({
		Default = "Crosshair",
		Values = { "Crosshair", "Closest", "Health" },
		Flag = "aim_priority",
		ToolTip = "Crosshair: nearest to your crosshair. Closest: nearest to you. Health: lowest health first",
		Callback = function(v) A.Priority = v end,
	});

	Sections.AimTarget:AddLabel("Visible Only"):AddToggle({
		Default = true, Flag = "aim_visible",
		ToolTip = "Ignore targets behind walls",
		Callback = function(v) A.Visible = v end,
	});

	Sections.AimTarget:AddLabel("FOV Radius"):AddSlider({
		Min = 10, Max = 600, Default = 220, Rounding = 0, Size = 90,
		Flag = "aim_fov",
		Callback = function(v) A.Fov = v end,
	});

	Sections.AimTarget:AddLabel("Max Distance"):AddSlider({
		Min = 0, Max = 1000, Default = 0, Type = "m", Rounding = 0, Size = 90,
		Flag = "aim_range",
		Callback = function(v) A.Range = v end,
	});

	Sections.AimTrigger:AddLabel("Triggerbot"):AddToggle({
		Default = false, Flag = "aim_trigger",
		ToolTip = "Shoots while the aim key is held and you are on a target",
		Callback = function(v) A.Trigger = v end,
	});

	Sections.AimTrigger:AddLabel("Fire Delay"):AddSlider({
		Min = 0, Max = 1000, Default = 150, Type = "ms", Rounding = 0, Size = 90,
		Flag = "aim_fire_delay",
		Callback = function(v) A.TriggerDelay = v end,
	});

	Sections.AimFov:AddLabel("Show Circle"):AddToggle({
		Default = true, Flag = "aim_circle",
		ToolTip = "Draws the aim FOV in the middle of the screen",
		Callback = function(v) A.Circle = v end,
	});

	Sections.AimFov:AddLabel("Dynamic Color"):AddToggle({
		Default = false, Flag = "aim_circle_dynamic",
		ToolTip = "Red while locked onto a target, white when nothing is locked",
		Callback = function(v) A.DynamicCircle = v end,
	});

	Sections.AimFov:AddLabel("Circle Color"):AddColorPicker({
		Default = A.CircleColor, Flag = "aim_circle_color",
		Callback = function(v) A.CircleColor = v end,
	});

	Sections.AimFov:AddLabel("Filled"):AddToggle({
		Default = false, Flag = "aim_circle_filled",
		Callback = function(v) A.CircleFilled = v end,
	});

	local detectedRow = Sections.SniperAim:AddLabel("Bots Found", true);
	local namesRow = Sections.SniperBots:AddLabel("Names", true);

	local botsRow = Sections.SniperAim:AddLabel("Aim at Bots"):AddToggle({
		Default = false, Flag = "aim_bots",
		ToolTip = "Targets the AI under workspace.Highlight.Enemy.HighlightHolder - names are random, they are found each frame",
		Callback = function(v) A.Bots = v end,
	});

	Sections.SniperBots:AddLabel("Bots Only"):AddToggle({
		Default = false, Flag = "aim_bots_only",
		ToolTip = "Ignores real players and only locks onto bots",
		Callback = function(v)
			A.BotsOnly = v;

			if v and not A.Bots then
				A.Bots = true;

				pcall(function() botsRow:Set(true) end);
			end;
		end,
	});

	task.spawn(function()
		while alive do
			local holder = botHolder();
			local names = {};

			if holder then
				for _, bot in ipairs(holder:GetChildren()) do
					if #botParts(bot) > 0 then names[#names + 1] = bot.Name end;
				end;
			end;

			detectedRow:SetText(tostring(#names));
			namesRow:SetText(#names > 0 and string.sub(table.concat(names, ", "), 1, 80) or "none");

			task.wait(1);
		end;
	end);

	onUnload("aimbot", function()
		alive = false;

		A.On, A.Trigger, A.Bots, A.BotsOnly = false, false, false, false;

		pcall(function() RunService:UnbindFromRenderStep(AIM_STEP) end);

		if stepConn then
			pcall(function() stepConn:Disconnect() end);

			stepConn = nil;
		end;

		if circle then
			circle.Visible = false;

			pcall(function() circle:Remove() end);

			circle = nil;
		end;
	end);
end);

guard("bot esp", function()
	local E = {
		On = false, Chams = false, Distance = true,
		Color = Color3.fromRGB(255, 84, 84),
	};

	local alive = true;
	local marks = {};
	local glows = {};

	local CORNERS = {
		Vector3.new(-0.5, -0.5, -0.5), Vector3.new(0.5, -0.5, -0.5),
		Vector3.new(-0.5, 0.5, -0.5), Vector3.new(0.5, 0.5, -0.5),
		Vector3.new(-0.5, -0.5, 0.5), Vector3.new(0.5, -0.5, 0.5),
		Vector3.new(-0.5, 0.5, 0.5), Vector3.new(0.5, 0.5, 0.5),
	};

	local function holder()
		local highlight = workspace:FindFirstChild("Highlight");
		local enemy = highlight and highlight:FindFirstChild("Enemy");

		return enemy and enemy:FindFirstChild("HighlightHolder") or nil;
	end;

	local function anchor(bot)
		local collider = bot:FindFirstChild("Collider");
		local head = collider and collider:FindFirstChild("Head");

		if not (head and head:IsA("BasePart")) then head = bot:FindFirstChild("Head", true) end;
		if not head then head = bot:FindFirstChildWhichIsA("BasePart", true) end;

		return head and head:IsA("BasePart") and head or nil;
	end;

	local function newMark()
		local okBox, box = pcall(function() return Drawing.new("Square") end);
		local okText, text = pcall(function() return Drawing.new("Text") end);

		if not okBox or not box or not okText or not text then
			pcall(function() if box then box:Remove() end end);
			pcall(function() if text then text:Remove() end end);

			return nil;
		end;

		box.Thickness = 1;
		box.Filled = false;
		box.Visible = false;

		text.Size = 14;
		text.Center = true;
		text.Outline = true;
		text.Font = Enum.Font.GothamMedium;
		text.Visible = false;

		return { box = box, name = text };
	end;

	local function drop(mark)
		if not mark then return end;

		pcall(function()
			mark.box.Visible = false;
			mark.name.Visible = false;
		end);

		pcall(function() mark.box:Remove() end);
		pcall(function() mark.name:Remove() end);
	end;

	local function screenBox(bot, camera)
		local ok, cf, size = pcall(function() return bot:GetBoundingBox() end);

		if not ok or not cf then
			local part = anchor(bot);

			if not part then return nil end;

			cf, size = part.CFrame, Vector3.new(2, 5, 2);
		end;

		local x0, y0, x1, y1;

		for _, corner in ipairs(CORNERS) do
			local point, on = camera:WorldToViewportPoint(cf * (corner * size));

			if on and point.Z > 0 then
				x0 = math.min(x0 or point.X, point.X);
				y0 = math.min(y0 or point.Y, point.Y);
				x1 = math.max(x1 or point.X, point.X);
				y1 = math.max(y1 or point.Y, point.Y);
			end;
		end;

		if not x0 then return nil end;

		return x0, y0, math.max(1, x1 - x0), math.max(1, y1 - y0);
	end;

	NeverLose:AddSignal(RunService.RenderStepped:Connect(function()
		if not alive or not NeverLose.ScreenGui.Parent then return end;

		local camera = workspace.CurrentCamera;
		local folder = E.On and camera and holder() or nil;
		local seen = {};

		if folder then
			for _, bot in ipairs(folder:GetChildren()) do
				local part = anchor(bot);

				if part then
					seen[bot] = true;

					local mark = marks[bot];

					if not mark then
						mark = newMark();
						marks[bot] = mark;
					end;

					if mark then
						local x, y, w, h = screenBox(bot, camera);

						if x then
							mark.box.Position = Vector2.new(x, y);
							mark.box.Size = Vector2.new(w, h);
							mark.box.Color = E.Color;
							mark.box.Visible = true;

							local label = bot.Name;

							if E.Distance then
								local away = (part.Position - camera.CFrame.Position).Magnitude;

								label = string.format("%s [%dm]", label, math.floor(away + 0.5));
							end;

							mark.name.Text = label;
							mark.name.Color = E.Color;
							mark.name.Position = Vector2.new(x + w * 0.5, math.max(4, y - 16));
							mark.name.Visible = true;
						else
							mark.box.Visible = false;
							mark.name.Visible = false;
						end;
					end;
				end;
			end;
		end;

		for bot, mark in pairs(marks) do
			if not seen[bot] then
				drop(mark);

				marks[bot] = nil;
			end;
		end;

		for bot in pairs(glows) do
			if not seen[bot] or not E.Chams then
				local glow = glows[bot];

				glows[bot] = nil;

				pcall(function() glow:Destroy() end);
			end;
		end;

		if E.Chams then
			for bot in pairs(seen) do
				local glow = glows[bot];

				if not glow then
					glow = Instance.new("Highlight");
					glow.Name = "BotChams";
					glow.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
					glow.Adornee = bot;
					glow.Parent = bot;
					glows[bot] = glow;
				end;

				glow.FillColor = E.Color;
				glow.OutlineColor = Color3.new(1, 1, 1);
				glow.FillTransparency = 0.35;
				glow.OutlineTransparency = 0.1;
			end;
		end;
	end));

	Sections.SniperEsp:AddLabel("Bot ESP"):AddToggle({
		Default = false, Flag = "bot_esp",
		ToolTip = "Box and name over the AI bots",
		Callback = function(v) E.On = v end,
	});

	Sections.SniperEsp:AddLabel("Distance"):AddToggle({
		Default = true, Flag = "bot_esp_dist",
		ToolTip = "Adds the distance to the name line",
		Callback = function(v) E.Distance = v end,
	});

	Sections.SniperEsp:AddLabel("Color"):AddColorPicker({
		Default = E.Color, Flag = "bot_esp_color",
		Callback = function(v) E.Color = v end,
	});

	Sections.SniperEsp:AddLabel("Bot Chams"):AddToggle({
		Default = false, Flag = "bot_chams",
		ToolTip = "Fills the bots through walls",
		Callback = function(v) E.Chams = v end,
	});

	onUnload("bot esp", function()
		alive = false;
		E.On, E.Chams = false, false;

		for bot, mark in pairs(marks) do
			drop(mark);

			marks[bot] = nil;
		end;

		for bot, glow in pairs(glows) do
			glows[bot] = nil;

			pcall(function() glow:Destroy() end);
		end;
	end);
end);

guard("server", function()
	local S = {
		Fling = false, Power = 150, Spin = false,
		Target = nil, Follow = false, Spectate = false,
	};

	local alive = true;
	local spinAngle = 0;
	local wasSpinning = false;
	local autoRotFor, autoRot = nil, nil;
	local savedCameraType;
	local startedAt = os.clock();
	local stats = game:GetService("Stats");
	local pingItem;

	local function targetNames()
		local names = {};

		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer then names[#names + 1] = player.Name end;
		end;

		table.sort(names);

		return names;
	end;

	local function findTarget()
		if type(S.Target) ~= "string" or S.Target == "" then return nil end;

		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer and player.Name == S.Target then return player end;
		end;

		return nil;
	end;

	local function roots()
		local mine = LocalPlayer.Character;
		local myRoot = mine and mine:FindFirstChild("HumanoidRootPart");
		local victim = findTarget();
		local theirRoot = victim and victim.Character and victim.Character:FindFirstChild("HumanoidRootPart");

		return myRoot, theirRoot;
	end;

	local function copy(value, label)
		local ok = type(setclipboard) == "function" and pcall(setclipboard, tostring(value or ""));

		Notification.new({
			Title = "Server",
			Content = ok and ("copied " .. label) or "no clipboard support",
			Duration = 3,
		});
	end;

	local function pingText()
		if not pingItem then
			local ok, item = pcall(function()
				return stats.Network.ServerStatsItem["Data Ping"];
			end);

			if ok then pingItem = item end;
		end;

		if not pingItem then return nil end;

		local ok, value = pcall(function() return pingItem:GetValueString() end);

		if ok and type(value) == "string" and value ~= "" then return value end;

		return nil;
	end;

	local names = targetNames();

	local targetDrop = Sections.FlingTarget:AddLabel("Target Player"):AddDropdown({
		Default = names[1],
		Values = names,
		Flag = "srv_target",
		Callback = function(v)
			S.Target = (type(v) == "string" and v ~= "") and v or nil;
		end,
	});

	S.Target = names[1];

	local function refreshTargets()
		local list = targetNames();

		if targetDrop.SetValues then targetDrop:SetValues(list) end;

		if not S.Target or not table.find(list, S.Target) then
			S.Target = list[1];

			if S.Target and targetDrop.SetValue then targetDrop:SetValue(S.Target) end;
		end;
	end;

	NeverLose:AddSignal(Players.PlayerAdded:Connect(function() task.defer(refreshTargets) end));
	NeverLose:AddSignal(Players.PlayerRemoving:Connect(function() task.defer(refreshTargets) end));

	NeverLose:AddSignal(RunService.Heartbeat:Connect(function(dt)
		if not alive then return end;

		local myRoot, theirRoot = roots();
		local human = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid");
		local spinning = S.Spin or (S.Fling and theirRoot ~= nil);

		if spinning and myRoot then
			spinAngle = (spinAngle + dt * 6) % (math.pi * 2);
			wasSpinning = true;
		elseif wasSpinning then
			if myRoot then pcall(function() myRoot.AssemblyAngularVelocity = Vector3.zero end) end;

			wasSpinning = false;
		end;

		if myRoot and human then
			if spinning then
				if autoRotFor ~= human then autoRotFor, autoRot = human, human.AutoRotate end;

				human.AutoRotate = false;
			elseif autoRotFor then
				if autoRotFor.Parent and autoRot ~= nil then autoRotFor.AutoRotate = autoRot end;

				autoRotFor, autoRot = nil, nil;
			end;
		end;

		if spinning and myRoot then
			if S.Fling and theirRoot then
				myRoot.CFrame = CFrame.new(theirRoot.Position) * CFrame.Angles(0, spinAngle, 0);
			else
				myRoot.CFrame = CFrame.new(myRoot.Position) * CFrame.Angles(0, spinAngle, 0);
			end;

			myRoot.AssemblyAngularVelocity = Vector3.new(0, S.Power, 0);
		end;

		if S.Follow and not S.Fling and myRoot and theirRoot then
			local delta = theirRoot.Position - myRoot.Position;

			if delta.Magnitude > 8 then
				myRoot.AssemblyLinearVelocity = delta.Unit * math.min(delta.Magnitude * 2, 160);
			end;
		end;

		if S.Spectate and theirRoot then
			local cam = workspace.CurrentCamera;

			if cam then
				if cam.CameraType ~= Enum.CameraType.Scriptable then
					savedCameraType = savedCameraType or cam.CameraType;
					cam.CameraType = Enum.CameraType.Scriptable;
				end;

				local at = theirRoot.Position;
				local back = -theirRoot.CFrame.LookVector;

				cam.CFrame = CFrame.lookAt(at + back * 7 + Vector3.new(0, 3, 0), at);
			end;
		elseif savedCameraType then
			local cam = workspace.CurrentCamera;

			if cam then cam.CameraType = savedCameraType end;

			savedCameraType = nil;
		end;
	end));

	Sections.FlingCtl:AddLabel("Fling"):AddToggle({
		Default = false, Flag = "srv_fling",
		ToolTip = "Sticks to the target and launches them",
		Callback = function(v) S.Fling = v end,
	});

	Sections.FlingCtl:AddLabel("Fling Power"):AddSlider({
		Min = 50, Max = 500, Default = 150, Rounding = 0, Size = 90,
		Flag = "srv_power",
		Callback = function(v) S.Power = v end,
	});

	Sections.FlingCtl:AddLabel("Spin"):AddToggle({
		Default = false, Flag = "srv_spin",
		ToolTip = "Spins your character in place",
		Callback = function(v) S.Spin = v end,
	});

	Sections.PlayerAct:AddButton({
		Icon = "map-pin",
		Name = "Teleport To Target",
		Callback = function()
			local myRoot, theirRoot = roots();

			if not myRoot or not theirRoot then
				Notification.new({ Title = "Server", Content = "Pick a target first", Duration = 3 });
				return;
			end;

			myRoot.CFrame = CFrame.new(theirRoot.Position + Vector3.new(0, 3, 0));
		end,
	});

	Sections.PlayerAct:AddLabel("Follow Target"):AddToggle({
		Default = false, Flag = "srv_follow",
		ToolTip = "Drifts towards the target",
		Callback = function(v) S.Follow = v end,
	});

	Sections.PlayerView:AddLabel("Spectate"):AddToggle({
		Default = false, Flag = "srv_spectate",
		ToolTip = "Camera follows the target",
		Callback = function(v)
			S.Spectate = v;

			if not v and savedCameraType then
				local cam = workspace.CurrentCamera;

				if cam then cam.CameraType = savedCameraType end;

				savedCameraType = nil;
			end;
		end,
	});

	Sections.PlayerView:AddButton({
		Icon = "copy",
		Name = "Copy Target Name",
		Callback = function()
			if not S.Target then
				Notification.new({ Title = "Server", Content = "Pick a target first", Duration = 3 });
				return;
			end;

			copy(S.Target, "name");
		end,
	});

	local playersLabel = Sections.ServerInfo:AddLabel("Players", true);
	local placeLabel = Sections.ServerInfo:AddLabel("Place Id", true);
	local jobLabel = Sections.ServerInfo:AddLabel("Job Id", true);
	local uptimeLabel = Sections.ServerSession:AddLabel("Uptime", true);
	local pingLabel = Sections.ServerSession:AddLabel("Ping", true);

	placeLabel:SetText(tostring(game.PlaceId));

	Sections.ServerInfo:AddButton({
		Icon = "copy",
		Name = "Copy Job Id",
		Callback = function() copy(game.JobId, "job id") end,
	});

	Sections.ServerSession:AddButton({
		Icon = "copy",
		Name = "Copy Join Link",
		Callback = function()
			copy(("roblox://experiences/start?placeId=%d&gameInstanceId=%s"):format(game.PlaceId, game.JobId), "join link");
		end,
	});

	task.spawn(function()
		while alive do
			local count = #Players:GetPlayers();

			playersLabel:SetText(count .. " / " .. Players.MaxPlayers);
			jobLabel:SetText(string.sub(tostring(game.JobId), 1, 8) .. "...");

			local seconds = math.floor(os.clock() - startedAt);

			uptimeLabel:SetText(string.format("%02d:%02d:%02d",
				math.floor(seconds / 3600), math.floor((seconds % 3600) / 60), seconds % 60));
			pingLabel:SetText(pingText() or "...");

			task.wait(1);
		end;
	end);

	onUnload("server", function()
		alive = false;
		S.Fling, S.Spin, S.Follow, S.Spectate = false, false, false, false;

		local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart");

		if root then pcall(function() root.AssemblyAngularVelocity = Vector3.zero end) end;

		if autoRotFor then
			if autoRotFor.Parent and autoRot ~= nil then autoRotFor.AutoRotate = autoRot end;

			autoRotFor, autoRot = nil, nil;
		end;

		if savedCameraType then
			local cam = workspace.CurrentCamera;

			if cam then cam.CameraType = savedCameraType end;

			savedCameraType = nil;
		end;
	end);
end);

guard("trade", function()
	local players = game:GetService("Players")
	local rs = game:GetService("ReplicatedStorage")
	local lp = players.LocalPlayer

	local show_on = false
	local conns = {}
	local gen = 0
	local sync = nil

	local env = GLOBAL
	env.__SV_STORE = env.__SV_STORE or { pages = {}, items = {}, fails = {}, busy = {} }
	local store = env.__SV_STORE
	local prefetch_gen = 0
	local id_index = nil

	local BASE = "https://r.jina.ai/https://supremevalues.com/mm2/"
	local PAGES = {
		"godlies", "chromas", "ancients", "uniques", "vintages",
		"legendaries", "rares", "uncommons", "commons", "pets", "misc"
	}
	local RARITY_PAGE = {
		Common = "commons",
		Uncommon = "uncommons",
		Rare = "rares",
		Legendary = "legendaries",
		Godly = "godlies",
		Ancient = "ancients",
		Unique = "uniques",
		Classic = "vintages",
		Vintage = "vintages",
		Christmas = "misc",
		Halloween = "misc",
	}
	local SKIP = {
		"^Class %-", "^Range", "^Stability", "^Demand", "^Rarity", "^Change in Value",
		"^Inv%.", "^Value", "^Tier", "^Filter", "^Sort", "^Title:", "^URL Source",
		"^Published Time", "^Markdown Content", "^%*", "^!%[", "^%[", "^%-", "^Supreme",
		"^Trade your", "^The Supreme", "^Chance of"
	}

	local LOW = "<1"

	local function norm(s)
		return (string.gsub(string.lower(tostring(s)), "[^%w]", ""))
	end

	local function comma(n)
		local s = tostring(math.floor(n + 0.5))
		while true do
			local r
			s, r = string.gsub(s, "^(-?%d+)(%d%d%d)", "%1,%2")
			if r == 0 then break end
		end
		return s
	end

	local function skip_line(t)
		for _, p in ipairs(SKIP) do
			if string.match(t, p) then return true end
		end
		return string.find(t, "%]%(") ~= nil or #t > 44
	end

	local function unwrap(t)
		return string.match(t, "^!%[.-%]%b()%s*(.+)$") or t
	end

	local function parse_page(txt, slug)
		local out = {}
		local last = nil
		for line in string.gmatch(txt .. "\n", "([^\n]*)\n") do
			local t = unwrap(string.match(line, "^%s*(.-)%s*$"))
			if t ~= "" then
				local raw = string.match(t, "^Value %- %*%*(.-)%*%*")
				if raw then
					if last then
						local clean = string.gsub(raw, "[,%s]", "")
						local num = tonumber(clean)
						if not num and string.match(clean, "^x%d+T%d") then num = LOW end
						if not num and #clean > 0 and #clean <= 12 then num = clean end
						local key = norm(last)
						if num and key ~= "" then
							if out[key] == nil then out[key] = num end
							if slug == "chromas" then
								local cut = string.match(key, "^chroma(.+)") or string.match(key, "^c(.+)")
								if cut and cut ~= "" and out[cut] == nil then out[cut] = num end
							end
						end
					end
					last = nil
				elseif not skip_line(t) then
					last = t
				end
			end
		end
		return out
	end

	local function valid_body(s)
		if type(s) ~= "string" or #s < 512 then return false end
		if not string.find(s, "Markdown Content", 1, true) then return false end
		return true
	end

	local function http_get(url)
		local ok, res = Remote.invoke(function() return game:HttpGet(url, true) end, 12)
		if ok and valid_body(res) then return res end
		local req = rawget(getfenv(), "request")
			or rawget(getfenv(), "http_request")
			or (syn and syn.request)
			or (http and http.request)
			or (fluxus and fluxus.request)
			or env.request
		if type(req) == "function" then
			local ok2, res2 = Remote.invoke(function() return req({
				Url = url,
				Method = "GET",
				Timeout = 12,
				Headers = { ["Accept"] = "text/plain", ["User-Agent"] = "Mozilla/5.0" }
			}) end, 12)
			if ok2 and type(res2) == "table" and valid_body(res2.Body) then return res2.Body end
		end
		return nil
	end

	local BACKOFF = { 2, 4, 6, 9 }
	local FAIL_COOLDOWN = 6

	local function get_page(slug)
		local cached = store.pages[slug]
		if cached then return cached end
		local deadline = os.clock() + 30
		while store.busy[slug] and Remote.current() do
			task.wait(0.2)
			if store.pages[slug] then return store.pages[slug] end
			if os.clock() >= deadline then return nil end
		end
		if not Remote.current() then return nil end
		if store.pages[slug] then return store.pages[slug] end
		local fail = store.fails[slug]
		if fail and os.clock() - fail < FAIL_COOLDOWN then return nil end
		local claim = {}
		store.busy[slug] = claim
		local built = nil
		for attempt = 1, #BACKOFF + 1 do
			if not Remote.current() then break end
			local txt = http_get(BASE .. slug)
			if txt then
				local ok, idx = pcall(parse_page, txt, slug)
				if ok and type(idx) == "table" and next(idx) ~= nil then
					built = idx
					break
				end
			end
			local nap = BACKOFF[attempt]
			if nap then task.wait(nap) end
		end
		if store.busy[slug] == claim then store.busy[slug] = nil end
		if not Remote.current() then return nil end
		if built then
			store.pages[slug] = built
			store.fails[slug] = nil
			return built
		end
		store.fails[slug] = os.clock()
		return nil
	end

	local function item_keys(data)
		local base = norm(data.ItemName or data.Name or "")
		local keys = {}
		if base == "" then return keys end
		local ty = data.ItemType and norm(tostring(data.ItemType)) or nil
		local yr = data.Year and norm(tostring(data.Year)) or nil
		local evo = data.EvoIndex and ("var" .. norm(tostring(data.EvoIndex))) or nil

		local seen = {}
		local function push(k)
			if k == "" or seen[k] then return end
			seen[k] = true
			keys[#keys + 1] = k
		end

		if evo then push(base .. evo) end
		if ty and yr then push(base .. ty .. yr) end
		if ty then push(base .. ty) end
		if yr then push(base .. yr) end
		push(base)
		return keys
	end

	local function page_list(data, dtype)
		if dtype == "Pets" then return { "pets" } end
		if data.Chroma then return { "chromas" } end
		local p = RARITY_PAGE[data.Rarity or ""]
		if p then return { p } end
		return { "misc" }
	end

	local function match_index(idx, keys)
		for _, k in ipairs(keys) do
			local v = idx[k]
			if v ~= nil then return v end
		end
		return nil
	end

	local function resolve(dtype, id, data)
		local ck = tostring(dtype) .. "|" .. tostring(id) .. (data.Chroma and "|c" or "")
		local hit = store.items[ck]
		if hit ~= nil then return hit, true end

		local keys = item_keys(data)
		if #keys == 0 then return false, true end

		local primary = page_list(data, dtype)
		local incomplete = false

		for _, slug in ipairs(primary) do
			local idx = get_page(slug)
			if idx then
				local v = match_index(idx, keys)
				if v ~= nil then
					store.items[ck] = v
					return v, true
				end
			else
				incomplete = true
			end
		end

		if not data.Chroma then
			for _, slug in ipairs(PAGES) do
				local skip = slug == "chromas"
				for _, x in ipairs(primary) do
					if x == slug then skip = true break end
				end
				if not skip then
					local idx = store.pages[slug]
					if idx then
						local v = match_index(idx, keys)
						if v ~= nil then
							store.items[ck] = v
							return v, true
						end
					elseif not store.fails[slug] then
						incomplete = true
					end
				end
			end
		end

		if incomplete then return nil, false end
		store.items[ck] = false
		return false, true
	end

	local function prefetch()
		prefetch_gen = prefetch_gen + 1
		local my = prefetch_gen
		store.fails = {}
		task.spawn(function()
			for sweep = 1, 4 do
				local left = 0
				for _, slug in ipairs(PAGES) do
					if my ~= prefetch_gen or not show_on then return end
					if not store.pages[slug] then
						get_page(slug)
						if not store.pages[slug] then left = left + 1 end
						task.wait(0.4)
					end
				end
				if left == 0 then return end
				if my ~= prefetch_gen or not show_on then return end
				task.wait(sweep * 4)
			end
		end)
	end

	local function trade_root()
		local pg = lp:FindFirstChildOfClass("PlayerGui")
		local gui = pg and pg:FindFirstChild("TradeGUI")
		local cont = gui and gui:FindFirstChild("Container")
		return cont and cont:FindFirstChild("Trade"), gui
	end

	local function make_label(parent, name, size, pos, anchor, maxtext, align)
		local l = parent:FindFirstChild(name)
		if l then
			l.AnchorPoint = anchor
			l.Position = pos
			l.Size = size
			l.TextXAlignment = align
			local c = l:FindFirstChildOfClass("UITextSizeConstraint")
			if c then c.MaxTextSize = maxtext end
			return l
		end
		l = Instance.new("TextLabel")
		l.Name = name
		l.AnchorPoint = anchor
		l.Position = pos
		l.Size = size
		l.BackgroundTransparency = 1
		l.BorderSizePixel = 0
		l.Font = Enum.Font.GothamBold
		l.TextColor3 = Color3.fromRGB(255, 216, 110)
		l.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
		l.TextStrokeTransparency = 0.15
		l.TextXAlignment = align
		l.TextScaled = true
		l.RichText = false
		l.ZIndex = 40
		l.Text = ""
		local con = Instance.new("UITextSizeConstraint")
		con.MaxTextSize = maxtext
		con.MinTextSize = 7
		con.Parent = l
		l.Parent = parent
		return l
	end

	local function total_label(offer)
		local l = make_label(offer, "SV_Total",
			UDim2.new(0.4, 0, 0, 22), UDim2.new(0.025, 0, 1, -137),
			Vector2.new(0, 1), 22, Enum.TextXAlignment.Left)

		local width = offer.AbsoluteSize.X
		local left = width * 0.025
		local title = offer:FindFirstChild("Title")
		if title and title.TextBounds.X > 4 then
			left = (title.AbsolutePosition.X - offer.AbsolutePosition.X) + title.TextBounds.X + 10
		end
		local limit = width - left - 8
		local user = offer:FindFirstChild("Username")
		if user and user.TextBounds.X > 4 then
			local edge = (user.AbsolutePosition.X - offer.AbsolutePosition.X) + user.AbsoluteSize.X - user.TextBounds.X
			limit = math.min(limit, edge - left - 8)
		end
		l.Position = UDim2.new(0, math.floor(left), 1, -137)
		l.Size = UDim2.new(0, math.max(60, math.floor(limit)), 0, 22)
		return l
	end

	local function card_label(card)
		local l = make_label(card, "SV_Value",
			UDim2.new(0.7, 0, 0.16, 0), UDim2.new(1, -6, 0, 4),
			Vector2.new(1, 0), 18, Enum.TextXAlignment.Right)

		local inner = card:FindFirstChild("Container")
		local amt = inner and inner:FindFirstChild("Amount")
		local stacked = amt and amt.Visible and string.match(amt.Text or "", "x%s*%d") ~= nil
		l.Position = UDim2.new(1, -6, 0, stacked and 32 or 4)
		return l
	end

	local function clear_side(offer)
		if not offer then return end
		local l = offer:FindFirstChild("SV_Total")
		if l then l.Visible = false end
		local cont = offer:FindFirstChild("Container")
		if not cont then return end
		for _, ch in ipairs(cont:GetChildren()) do
			local v = ch:FindFirstChild("SV_Value")
			if v then v.Visible = false end
		end
	end

	local function wipe_labels()
		local root = trade_root()
		if not root then return end
		for _, side in ipairs({ "YourOffer", "TheirOffer" }) do
			local offer = root:FindFirstChild(side)
			if offer then
				local l = offer:FindFirstChild("SV_Total")
				if l then l:Destroy() end
				local cont = offer:FindFirstChild("Container")
				if cont then
					for _, ch in ipairs(cont:GetChildren()) do
						local v = ch:FindFirstChild("SV_Value")
						if v then v:Destroy() end
					end
				end
			end
		end
	end

	local function ensure_sync()
		if sync then return sync end
		local database = rs:FindFirstChild("Database")
		local module = database and database:FindFirstChild("Sync")
		if not module or not module:IsA("ModuleScript") then return nil end
		local ok, mod = Remote.invoke(function() return require(module) end, 5)
		if ok and type(mod) == "table" then sync = mod end
		return sync
	end

	local function build_index()
		if id_index then return id_index end
		if not ensure_sync() then return nil end
		local byid, byname = {}, {}
		local function add(map, key, rec)
			if not key or key == "" then return end
			local bucket = map[key]
			if bucket then
				bucket[#bucket + 1] = rec
			else
				map[key] = { rec }
			end
		end
		for _, dtype in ipairs({ "Weapons", "Pets" }) do
			local db = sync[dtype]
			if type(db) == "table" then
				for id, d in pairs(db) do
					if type(d) == "table" then
						local rec = { dtype = dtype, id = id, data = d }
						if d.ItemID then add(byid, tostring(d.ItemID), rec) end
						if type(d.Image) == "string" then
							local dig = string.match(d.Image, "assetId=(%d+)")
								or string.match(d.Image, "id=(%d+)")
								or string.match(d.Image, "rbxassetid://(%d+)")
							if dig then add(byid, dig, rec) end
						end
						add(byname, tostring(d.ItemName or d.Name or ""), rec)
					end
				end
			end
		end
		id_index = { byid = byid, byname = byname }
		return id_index
	end

	local function icon_id(card)
		local inner = card:FindFirstChild("Container")
		local icon = inner and inner:FindFirstChild("Icon")
		local img = icon and icon.Image or ""
		if img == "" then return nil end
		return string.match(img, "assetId=(%d+)")
			or string.match(img, "id=(%d+)")
			or string.match(img, "rbxassetid://(%d+)")
	end

	local function card_entry(card, text, chroma)
		local ix = build_index()
		if not ix then return nil end
		local iid = icon_id(card)
		local pool = iid and ix.byid[iid] or nil
		if not pool then pool = ix.byname[text] end
		if not pool then return nil end

		local fallback = nil
		for _, rec in ipairs(pool) do
			local d = rec.data
			if (d.Chroma == true) == chroma then
				if tostring(d.ItemName or d.Name or "") == text then return rec.dtype, rec.id, d end
				if not fallback then fallback = rec end
			end
		end
		if fallback then return fallback.dtype, fallback.id, fallback.data end
		if iid and ix.byid[iid] == pool then
			local rec = pool[1]
			return rec.dtype, rec.id, rec.data
		end
		return nil
	end

	local function gui_items(offer)
		local out = {}
		local cont = offer and offer:FindFirstChild("Container")
		if not cont then return out end
		local i = 1
		while true do
			local card = cont:FindFirstChild("NewItem" .. i)
			if not card or not card.Visible then break end
			local nm = card:FindFirstChild("ItemName")
			local lbl = nm and nm:FindFirstChild("Label")
			local text = lbl and lbl.Text or ""
			if text == "" then break end
			local tags = card:FindFirstChild("Tags")
			local ch = tags and tags:FindFirstChild("Chroma")
			local inner = card:FindFirstChild("Container")
			local amt_l = inner and inner:FindFirstChild("Amount")
			local amt = amt_l and tonumber(string.match(amt_l.Text or "", "x%s*(%d+)")) or 1
			local chroma = ch ~= nil and ch.Visible == true
			local dtype, id, data = card_entry(card, text, chroma)
			out[i] = {
				id = id or norm(text),
				amount = amt,
				dtype = dtype or "Weapons",
				data = data or { ItemName = text, Chroma = chroma }
			}
			i = i + 1
		end
		return out
	end

	local function collect(offer_data)
		local out = {}
		if type(offer_data) ~= "table" then return out end
		ensure_sync()
		for i, v in ipairs(offer_data) do
			local id = v[1] or v.ItemID
			local amount = v[2] or v.Amount or 1
			local dtype = v[3] or v.ItemType
			local db = sync and dtype and sync[dtype]
			local data = db and db[id]
			out[i] = { id = id, amount = amount, dtype = dtype, data = data }
		end
		return out
	end

	local function render(offer, items, my_gen)
		if not offer then return end
		local cont = offer:FindFirstChild("Container")
		if not cont then return end
		clear_side(offer)
		local total = total_label(offer)
		if #items == 0 then
			total.Visible = false
			return
		end
		total.Visible = true
		total.Text = "..."
		for i in ipairs(items) do
			local card = cont:FindFirstChild("NewItem" .. i)
			if card then
				local l = card_label(card)
				l.Visible = true
				l.Text = "..."
			end
		end
		task.spawn(function()
			local done = {}
			local deadline = os.clock() + 150
			while true do
				local pending = false
				local sum = 0
				for i, it in ipairs(items) do
					if my_gen ~= gen or not show_on then return end
					if done[i] == nil then
						if it.data then
							local fine, val, settled = pcall(resolve, it.dtype, it.id, it.data)
							if not fine then
								done[i] = { v = false }
							elseif settled then
								done[i] = { v = val }
							else
								pending = true
							end
						else
							done[i] = { v = false }
						end
					end
					if my_gen ~= gen or not show_on then return end
					local card = cont:FindFirstChild("NewItem" .. i)
					local l = card and card:FindFirstChild("SV_Value")
					local rec = done[i]
					if rec then
						local val = rec.v
						local amt = tonumber(it.amount) or 1
						if type(val) == "number" then
							sum = sum + val * amt
							if l then l.Text = comma(val) end
						elseif type(val) == "string" then
							if l then l.Text = val end
						elseif l then
							l.Text = "?"
						end
					elseif l then
						l.Text = "..."
					end
				end
				if total.Parent then
					total.Text = pending and (comma(sum) .. " ...") or comma(sum)
				end
				if not pending then return end
				if os.clock() > deadline then
					for i in ipairs(items) do
						if done[i] == nil then
							local card = cont:FindFirstChild("NewItem" .. i)
							local l = card and card:FindFirstChild("SV_Value")
							if l then l.Text = "?" end
						end
					end
					if total.Parent then total.Text = comma(sum) end
					return
				end
				task.wait(2)
			end
		end)
	end

	local function update(data)
		if not show_on or type(data) ~= "table" then return end
		local mine, theirs
		if data.Player1 and data.Player1.Player == lp then
			mine, theirs = data.Player1.Offer, data.Player2 and data.Player2.Offer
		elseif data.Player2 and data.Player2.Player == lp then
			mine, theirs = data.Player2.Offer, data.Player1 and data.Player1.Offer
		else
			return
		end
		gen = gen + 1
		local my_gen = gen
		local my_items, their_items = collect(mine), collect(theirs)
		task.delay(0.05, function()
			if my_gen ~= gen or not show_on then return end
			local root = trade_root()
			if not root then return end
			render(root:FindFirstChild("YourOffer"), my_items, my_gen)
			render(root:FindFirstChild("TheirOffer"), their_items, my_gen)
		end)
	end

	local function refresh_gui()
		if not show_on then return end
		local root, gui = trade_root()
		if not root or not gui or not gui.Enabled then return end
		gen = gen + 1
		local my_gen = gen
		local mine = root:FindFirstChild("YourOffer")
		local theirs = root:FindFirstChild("TheirOffer")
		render(mine, gui_items(mine), my_gen)
		render(theirs, gui_items(theirs), my_gen)
	end

	local function hook()
		local trade = rs:FindFirstChild("Trade")
		if not trade then return end
		local upd = trade:FindFirstChild("UpdateTrade")
		local start = trade:FindFirstChild("StartTrade")
		if upd then
			conns[#conns + 1] = upd.OnClientEvent:Connect(update)
		end
		if start then
			conns[#conns + 1] = start.OnClientEvent:Connect(function(data)
				update(data)
			end)
		end
		local _, gui = trade_root()
		if gui then
			conns[#conns + 1] = gui:GetPropertyChangedSignal("Enabled"):Connect(function()
				if not gui.Enabled then
					gen = gen + 1
					local root = trade_root()
					if root then
						clear_side(root:FindFirstChild("YourOffer"))
						clear_side(root:FindFirstChild("TheirOffer"))
					end
				end
			end)
		end
	end

	local function unhook()
		for _, c in ipairs(conns) do
			pcall(function() c:Disconnect() end)
		end
		conns = {}
	end

	Sections.Trade:AddLabel("Show Values"):AddToggle({
		Name = "Show Values",
		Default = false,
		Flag = "trade_show_values",
		ToolTip = "Shows trade values",
		Callback = function(v)
			show_on = v
			gen = gen + 1
			if v then
				unhook()
				hook()
				prefetch()
				refresh_gui()
			else
				prefetch_gen = prefetch_gen + 1
				unhook()
				wipe_labels()
			end
		end,
	});

	Sections.Trade:AddButton({
		Icon = "arrow-rotate-right",
		Name = "Refresh Values",
		Callback = function()
			if not show_on then return end;

			store.pages = {};
			store.items = {};
			store.fails = {};

			prefetch();
			refresh_gui();
		end,
	});

	ESP.ClearTrade = function()
		show_on = false
		gen = gen + 1
		prefetch_gen = prefetch_gen + 1
		unhook()
		wipe_labels()
	end;
end);

guard("menu", function()

	local HttpService = game:GetService("HttpService");
	local ContentProvider = game:GetService("ContentProvider");
	local function fileExists(path)
		return Remote.listedPath(path);
	end;
	local function assetUrl(path)
		return Remote.id(path);
	end;
	local function readManifest(path)
		local body = Remote.body(path);
		if not body then return nil end;
		local ok, records = pcall(function() return HttpService:JSONDecode(body) end);
		return ok and type(records) == "table" and records or nil;
	end;
	local function localPath(relative)
		if type(relative) ~= "string" or relative == "" or relative:find("..", 1, true) or relative:find(":", 1, true) then return nil end;
		return Remote.file(relative);
	end;

	local function listFolder(relative)
		return Remote.under(relative .. "/");
	end;

	local function prettyName(name)
		local text = tostring(name or ""):match("^%s*(.-)%s*$");

		if text == "" then return "Untitled" end;

		return (text:gsub("[_%-]+", " "):gsub("(%a)(%d)", "%1 %2"):gsub("(%a[%w']*)", function(word)
			return word:sub(1, 1):upper() .. word:sub(2);
		end));
	end;

	do
		local hour = 12;
		local ok, clock = pcall(os.date, "*t");
		if ok and type(clock) == "table" and type(clock.hour) == "number" then
			hour = math.clamp(math.floor(clock.hour), 0, 23);
		else
			pcall(function() hour = DateTime.now():ToLocalTime().Hour end);
		end;
		local greeting = "dobry-vecher";
		if hour >= 5 and hour < 11 then
			greeting = "dobroe-utrechko";
		elseif hour >= 11 and hour < 17 then
			greeting = "dobry-denb";
		elseif hour >= 17 and hour < 22 then
			greeting = "dobry-vecher";
		end;
		ESP.Greeting = { Hour = hour, File = "sounds/time/" .. greeting .. ".ogg" };
		local url = assetUrl(Remote.file(ESP.Greeting.File));
		if url then
			local sound = Instance.new("Sound");
			sound:SetAttribute("VisualsOwned", true);
			sound.Name = NeverLose.RandomString();
			sound.SoundId = url;
			sound.Volume = 0.5;
			sound.Parent = NeverLose.ScreenGui;
			NeverLose:AddSignal(sound.Ended:Connect(function() sound:Destroy() end));
			game:GetService("Debris"):AddItem(sound, 30);
			sound:Play();
			ESP.Greeting.Sound = sound;
		end;
	end;

	local presets, order = {}, { "Off" };
	local records = readManifest("menusounds/manifest.json");
	if records then
		for _, entry in ipairs(records) do
			if type(entry) == "table" and type(entry.name) == "string" and entry.name ~= "Off" then
				local on, off = localPath(entry.on), localPath(entry.off);
				if on and fileExists(on) and not presets[entry.name] then
					presets[entry.name] = { on = on, off = off and fileExists(off) and off or nil };
					order[#order + 1] = entry.name;
				end;
			end;
		end;
	else
		local pairsFound, names = {}, {};
		for _, rel in ipairs(listFolder("menusounds")) do
			local file = string.match(rel, "([^/]+)$") or "";
			local name, side, extension = string.match(file:lower(), "^(.+)_(o[nf]f?)%.(%w+)$");
			if name and (extension == "wav" or extension == "ogg" or extension == "mp3") and fileExists(Remote.file(rel)) then
				if not pairsFound[name] then pairsFound[name] = {}; names[#names + 1] = name end;
				pairsFound[name][side] = Remote.file(rel);
			end;
		end;
		table.sort(names);
		for _, name in ipairs(names) do
			local entry = pairsFound[name];
			if entry.on then
				local label = prettyName(name) .. (entry.off and "" or " (ON only)");
				presets[label] = entry; order[#order + 1] = label;
			end;
		end;
	end;

	local M = { Preset = "Off", Volume = 50 };
	local onSound = ownedSound();
	onSound.Name = NeverLose.RandomString();
	onSound.Parent = NeverLose.ScreenGui;
	local offSound = onSound:Clone();
	offSound.Parent = NeverLose.ScreenGui;
	local soundSelection = 0;
	local click;
	local function loadPreset(name, preview)
		soundSelection += 1;
		local selection = soundSelection;
		local playPreview = preview and not NeverLose.Lib.quiet;
		onSound:Stop(); offSound:Stop();
		onSound.SoundId = ""; offSound.SoundId = "";
		local entry = presets[name];
		if not entry then return end;
		local function wanted()
			return Remote.current() and selection == soundSelection and M.Preset == name and onSound.Parent ~= nil and offSound.Parent ~= nil;
		end;
		task.spawn(function()
			local on = assetUrl(entry.on);
			if not wanted() then return end;

			local off = entry.off and assetUrl(entry.off) or "";
			if not wanted() then return end;
			onSound.SoundId = on or ""; offSound.SoundId = off or "";
			if playPreview then click(true) end;
		end);
	end;
	click = function(state)
		if M.Preset == "Off" or M.Volume <= 0 then return end;
		local sound = state and onSound or offSound;
		if not sound.Parent or sound.SoundId == "" then return end;
		sound.Volume = M.Volume / 100;
		sound.TimePosition = 0;
		sound:Play();
	end;
	ESP.MenuClick = click;
	ESP.MenuSounds = M;

	local lib = NeverLose.Lib;
	local OFF_KINDS = { off = true, close = true };

	function lib:chime(kind)
		if M.Preset == "Off" or M.Volume <= 0 then return end;
		if lib.quiet then return end;

		click(not OFF_KINDS[kind]);
	end;

	NeverLose.OnToggleChanged = function(_, flag, _)
		if Preview and Preview.Queue then Preview.Queue(flag) end;
	end;
	Sections.MenuSounds:AddLabel("Preset"):AddDropdown({
		Default = "Off", Values = order, Flag = "menu_sound",
		Callback = function(value) M.Preset = value; loadPreset(value, true) end,
	});
	Sections.MenuSounds:AddLabel("Volume"):AddSlider({
		Min = 0, Max = 100, Default = 50, Type = "%", Size = 100, Flag = "menu_sound_volume",
		Callback = function(value) M.Volume = value end,
	});

	local sheets, stickerOrder = {}, { "Off" };
	local function addSheet(record)
		if type(record) ~= "table" or type(record.name) ~= "string" or record.name == "Off" or sheets[record.name] then return end;
		local cols, rows = tonumber(record.cols), tonumber(record.rows);
		local width, height, frames = tonumber(record.width), tonumber(record.height), tonumber(record.frames);
		if not (cols and rows and width and height and frames) then return end;
		if cols < 1 or rows < 1 or frames < 1 or cols % 1 ~= 0 or rows % 1 ~= 0 or frames % 1 ~= 0 then return end;
		if width % cols ~= 0 or height % rows ~= 0 or width < cols or height < rows then return end;
		local files = {};
		for _, relative in ipairs(record.sheets or { record.file }) do
			local path = localPath(relative);
			if not (path and fileExists(path)) then return end;
			files[#files + 1] = path;
		end;
		if #files == 0 or frames > cols * rows * #files then return end;
		sheets[record.name] = {
			files = files, cols = cols, rows = rows, frames = frames,
			cellWidth = width / cols, cellHeight = height / rows,
			fps = math.clamp(tonumber(record.fps) or 15, 1, 120),
		};
		stickerOrder[#stickerOrder + 1] = record.name;
	end;
	local stickerRecords = readManifest("stickers/manifest.json");
	if stickerRecords then for _, record in ipairs(stickerRecords) do addSheet(record) end end;
	addSheet({ name = "Fury", sheets = {
		"images/furynew_sheet_1.png", "images/furynew_sheet_2.png", "images/furynew_sheet_3.png",
	}, width = 1024, height = 768, cols = 4, rows = 3, frames = 35, fps = 12 });

	local CUSTOM = "Salad Visuals/Stickers";
	local customNames = {};
	local function imageSize(path)
		if not readfile then return nil end;
		local ok, raw = pcall(readfile, path);
		if not ok or type(raw) ~= "string" or #raw < 24 or #raw > 16 * 1024 * 1024 then return nil end;
		local function uint(at, count)
			if at + count - 1 > #raw then return nil end;
			local value = 0;
			for index = at, at + count - 1 do value = value * 256 + raw:byte(index) end;
			return value;
		end;
		local width, height;
		if raw:sub(1, 8) == "\137PNG\13\10\26\10" and raw:sub(13, 16) == "IHDR" then
			width, height = uint(17, 4), uint(21, 4);
		elseif raw:byte(1) == 255 and raw:byte(2) == 216 then
			local at = 3;
			while at < #raw do
				if raw:byte(at) ~= 255 then break end;
				while raw:byte(at) == 255 do at += 1 end;
				local marker = raw:byte(at); at += 1;
				if not marker or marker == 217 or marker == 218 then break end;
				if marker ~= 1 and not (marker >= 208 and marker <= 216) then
					local length = uint(at, 2);
					if not length or length < 2 or at + length - 1 > #raw then break end;
					if marker >= 192 and marker <= 207 and marker ~= 196 and marker ~= 200 and marker ~= 204 then
						if length < 8 then break end;
						height, width = uint(at + 3, 2), uint(at + 5, 2); break;
					end;
					at += length;
				end;
			end;
		end;
		if width and height and width >= 1 and height >= 1 and width <= 8192 and height <= 8192 then return width, height end;
	end;

	local function scanCustom()
		if not (isfolder and listfiles and isfile) then return end;
		if not isfolder(CUSTOM) then
			if makefolder then pcall(makefolder, CUSTOM) end;

			return;
		end;

		local found = {};

		local ok = pcall(function()
			for _, path in ipairs(listfiles(CUSTOM)) do
				local file = string.match(path, "([^/\\]+)$") or "";
				local extension = string.match(string.lower(file), "%.(%w+)$");

				if extension == "png" or extension == "jpg" or extension == "jpeg" then
					found[#found + 1] = { path = path, file = file };
				end;
			end;
		end);

		if not ok then return end;

		table.sort(found, function(a, b) return string.lower(a.file) < string.lower(b.file) end);
		for _, name in ipairs(customNames) do
			sheets[name] = nil;
			local index = table.find(stickerOrder, name);
			if index then table.remove(stickerOrder, index) end;
		end;
		table.clear(customNames);

		for _, entry in ipairs(found) do
			local stem = string.gsub(entry.file, "%.%w+$", "");
			local base, cols, rows, frames = string.match(stem, "^(.+)_(%d+)x(%d+)_(%d+)$");
			local name = prettyName(base or stem);

			if sheets[name] then name = name .. " (mine)" end;
			local baseName, suffix = name, 2;
			while sheets[name] do name = baseName .. " " .. suffix; suffix += 1 end;
			local width, height = imageSize(entry.path);
			cols, rows, frames = tonumber(cols), tonumber(rows), tonumber(frames);
			if cols and (not width or cols < 1 or rows < 1 or cols > 64 or rows > 64
				or frames < 1 or frames > cols * rows or width % cols ~= 0 or height % rows ~= 0) then
				warn("[visuals] invalid sticker sheet: " .. entry.file);
				continue;
			end;

			if not sheets[name] then
				if cols then
					sheets[name] = {
						files = { entry.path }, cols = tonumber(cols), rows = tonumber(rows),
						frames = frames, cellWidth = width / cols, cellHeight = height / rows,
						fps = 15, custom = true, sheet = true,
					};
				else

					sheets[name] = {
						files = { entry.path }, cols = 1, rows = 1, frames = 1,
						fps = 1, custom = true, whole = true,
						cellWidth = width or 1, cellHeight = height or 1,
					};
				end;

				stickerOrder[#stickerOrder + 1] = name;
				customNames[#customNames + 1] = name;
			end;
		end;
	end;

	if #stickerOrder == 1 then
		local legacy = {};
		for _, path in ipairs(listFolder("stickers")) do
			local file = string.match(path, "([^/\\]+)$") or "";
			local name, cols, rows, frames = string.match(file, "^(.+)_(%d+)x(%d+)_(%d+)%.png$");
			if name then
				legacy[#legacy + 1] = { name = prettyName(name), file = "stickers/" .. file, cols = tonumber(cols), rows = tonumber(rows), frames = tonumber(frames), width = 128 * tonumber(cols), height = 128 * tonumber(rows), fps = 15 };
			end;
		end;
		table.sort(legacy, function(a, b) return a.name < b.name end);
		for _, record in ipairs(legacy) do addSheet(record) end;
	end;

	local ST = {
		Name = "Fury", Size = 176, Speed = 100, Opacity = 100, Side = "Header",
		Raise = 0, OffsetX = 0, OffsetY = 0, Layer = 60,
	};
	local holder = Instance.new("ImageLabel");
	holder.Name = "VisualsMenuSticker";
	holder.BackgroundTransparency = 1;
	holder.BorderSizePixel = 0;
	holder.ScaleType = Enum.ScaleType.Fit;
	holder.ImageColor3 = Color3.new(1, 1, 1);
	holder.ImageTransparency = 1;
	holder.Visible = false;
	holder.Active = false;
	holder.ZIndex = 60;
	holder.Parent = NeverLose.ScreenGui;
	local current, frame, elapsed, opacity = nil, 0, 0, 0;
	local pageLayers, activeLayer = {}, nil;
	local stickerSelection = 0;
	local menuOpen = Window.Signal:GetValue();
	local function clearLayers()
		activeLayer = nil;
		for _, layer in ipairs(pageLayers) do layer:Destroy() end;
		table.clear(pageLayers);
	end;
	local function prepareLayers(urls)
		clearLayers();
		for _, url in ipairs(urls) do
			local layer = Instance.new("ImageLabel");
			layer.Name = "VisualsMenuStickerLayer" .. tostring(#pageLayers + 1);
			layer.Size = UDim2.fromScale(1, 1);
			layer.BackgroundTransparency = 1;
			layer.BorderSizePixel = 0;
			layer.Image = url;
			layer.ImageColor3 = Color3.new(1, 1, 1);
			layer.ImageTransparency = 1;
			layer.ScaleType = Enum.ScaleType.Fit;
			layer.Visible = false;
			layer.Active = false;
			layer.ZIndex = ST.Layer;
			layer.Parent = holder;
			pageLayers[#pageLayers + 1] = layer;
		end;
		return table.clone(pageLayers);
	end;
	local function place()
		local window = ESP.WindowFrame and ESP.WindowFrame();
		if not (window and current) then return end;
		local screen = NeverLose.ScreenGui.AbsoluteSize;
		local size = math.min(ST.Size, math.max(16, screen.X - 4), math.max(16, screen.Y - 4));

		if NeverLose.Mobile then size = math.min(size, screen.Y * 0.4) end;
		local ratio = current.cellWidth / current.cellHeight;
		local width, height = size * math.min(1, ratio), size / math.max(1, ratio);
		local at, box = window.AbsolutePosition, window.AbsoluteSize;
		local origin = holder.AbsolutePosition - Vector2.new(holder.Position.X.Offset, holder.Position.Y.Offset);
		local x, y;

		if ST.Side == "Header" then x, y = at.X - width * 0.18, at.Y - height * 0.22;
		elseif ST.Side == "Header Right" then x, y = at.X + box.X - width * 0.82, at.Y - height * 0.22;
		elseif ST.Side == "Right" then x, y = at.X + box.X - width * 0.25, at.Y + box.Y - height;
		else x, y = at.X - width * 0.75, at.Y + box.Y - height end;

		x = math.clamp(x + ST.OffsetX, -width + 8, math.max(8, screen.X - 8));
		y = math.clamp(y + ST.OffsetY - ST.Raise, -height + 8, math.max(8, screen.Y - 8));

		if NeverLose.Mobile then
			local top = NeverLose.ScreenGui.AbsolutePosition.Y + game:GetService("GuiService"):GetGuiInset().Y;
			local bottom = NeverLose.ScreenGui.AbsolutePosition.Y + screen.Y;
			x = math.clamp(x, 0, math.max(0, screen.X - width));
			y = math.clamp(y, top, math.max(top, bottom - height));
		end;
		holder.Size = UDim2.fromOffset(width, height);
		holder.ZIndex = ST.Layer;
		for _, layer in ipairs(pageLayers) do layer.ZIndex = ST.Layer end;
		holder.Position = UDim2.fromOffset(x - origin.X, y - origin.Y);
	end;
	local function drawFrame()
		if not current then return end;
		local layer = pageLayers[1];
		if not layer then return end;

		if current.whole then
			layer.ImageRectSize = Vector2.new();
			layer.ImageRectOffset = Vector2.new();
		else
			local capacity = current.cols * current.rows;
			local page = math.floor(frame / capacity) + 1;
			local localFrame = frame % capacity;
			layer = pageLayers[page];
			if not (layer and current.cellWidth and current.cellHeight) then return end;
			layer.ImageRectSize = Vector2.new(current.cellWidth, current.cellHeight);
			layer.ImageRectOffset = Vector2.new((localFrame % current.cols) * current.cellWidth, math.floor(localFrame / current.cols) * current.cellHeight);
		end;
		if activeLayer ~= layer then
			if activeLayer then activeLayer.Visible = false; activeLayer.ImageTransparency = 1 end;
			activeLayer = layer;
			activeLayer.Visible = true;
		end;
		activeLayer.ImageTransparency = 1 - math.clamp(opacity, 0, 1);
	end;
	local function select(name)
		stickerSelection += 1;
		local selection = stickerSelection;
		current = nil; frame = 0; elapsed = 0; opacity = 0;
		clearLayers();
		holder.Visible = false; holder.ImageTransparency = 1;
		ST.Error = nil;
		local entry = sheets[name];
		if not entry then return end;
		local function wanted()
			return Remote.current() and selection == stickerSelection and ST.Name == name and holder.Parent ~= nil;
		end;
		local function show(urls)
			if not wanted() then return end;
			local layers = prepareLayers(urls);
			if not wanted() then return end;

			Remote.invoke(function() ContentProvider:PreloadAsync(layers) end, 5);
			if not wanted() then return end;
			current = entry;
			drawFrame(); place();
		end;

		task.spawn(function()
			local ok, reason = pcall(function()
				local resolved = entry.urls;
				if not resolved then
					resolved = {};
					for _, path in ipairs(entry.files) do
						if not wanted() then return end;
						local url = assetUrl(path);
						if not wanted() then return end;
						if not url then ST.Error = "Unable to load " .. path; return end;
						resolved[#resolved + 1] = url;
					end;
					entry.urls = resolved;
				end;
				show(resolved);
			end);
			if not ok and wanted() then ST.Error = tostring(reason) end;
		end);
	end;
	NeverLose:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not (NeverLose.ScreenGui.Parent and holder.Parent) then return end;
		local target = current and menuOpen and ST.Opacity / 100 or 0;
		opacity = opacity + (target - opacity) * (1 - math.exp(-18 * math.max(dt, 0)));
		if math.abs(target - opacity) < 0.001 then opacity = target end;
		holder.Visible = current ~= nil and opacity > 0.001;
		if activeLayer then activeLayer.ImageTransparency = 1 - math.clamp(opacity, 0, 1) end;
		if not current or not holder.Visible then return end;
		place();
		if not menuOpen or current.frames <= 1 then return end;
		local fps = current.fps * ST.Speed / 100;
		elapsed = elapsed + dt;
		local steps = math.floor(elapsed * fps);
		if steps < 1 then return end;
		elapsed = elapsed - steps / fps;
		frame = (frame + steps) % current.frames;
		drawFrame();
	end));
	local stickerDrop = Sections.MenuSticker:AddLabel("Sticker"):AddDropdown({

		Default = NeverLose.Mobile and "Off" or "Fury", Values = stickerOrder, Flag = "menu_sticker",
		Callback = function(value) ST.Name = value; select(value) end,
	});
	task.defer(function()
		if not Remote.current() then return end;
		scanCustom();
		if Remote.current() and stickerDrop and stickerDrop.SetValues then
			stickerDrop:SetValues(stickerOrder);
		end;
	end);

	Sections.MenuSticker:AddButton({
		Icon = "refresh-cw", Name = "Reload Stickers",
		Callback = function()
			local before = #stickerOrder;

			scanCustom();
			if not sheets[ST.Name] then ST.Name = "Off" end;
			select(ST.Name);

			if stickerDrop and stickerDrop.SetValues then
				pcall(stickerDrop.SetValues, stickerDrop, stickerOrder);
			end;

			Notification.new({
				Title = "Stickers",
				Content = (#stickerOrder - before) .. " added, " .. #customNames .. " custom",
				Duration = 4,
			});
		end,
	});
	Sections.MenuSticker:AddLabel("Spot"):AddDropdown({
		Default = "Header", Values = { "Header", "Header Right", "Right", "Left" }, Flag = "menu_sticker_side",
		Callback = function(value) ST.Side = value; place() end,
	});
	Sections.MenuSticker:AddLabel("Size"):AddSlider({
		Min = 40, Max = 700, Default = 176, Rounding = 0, Size = 100, Flag = "menu_sticker_size",
		Callback = function(value) ST.Size = value; place() end,
	});
	Sections.MenuSticker:AddLabel("Playback Speed"):AddSlider({
		Min = 10, Max = 200, Default = 100, Rounding = 0, Type = "%", Size = 100, Flag = "menu_sticker_speed",
		Callback = function(value) ST.Speed = value end,
	});
	Sections.MenuSticker:AddLabel("Opacity"):AddSlider({
		Min = 0, Max = 100, Default = 100, Rounding = 0, Type = "%", Size = 100, Flag = "menu_sticker_opacity",
		Callback = function(value) ST.Opacity = value end,
	});

	Sections.MenuSticker:AddLabel("Offset X"):AddSlider({
		Min = -200, Max = 200, Default = 0, Rounding = 0, Size = 100, Flag = "menu_sticker_x",
		Callback = function(value) ST.OffsetX = value; place() end,
	});
	Sections.MenuSticker:AddLabel("Offset Y"):AddSlider({
		Min = -200, Max = 200, Default = 0, Rounding = 0, Size = 100, Flag = "menu_sticker_y",
		Callback = function(value) ST.OffsetY = value; place() end,
	});

	Sections.MenuSticker:AddLabel("Layer"):AddSlider({
		Min = 1, Max = 120, Default = 60, Rounding = 0, Size = 100, Flag = "menu_sticker_z",
		Callback = function(value) ST.Layer = value; place() end,
	});
	Window.Signal:Connect(function(open) menuOpen = open end);
	ESP.Sticker = ST;
	ESP.ClearMenuExtras = function()
		stickerSelection += 1;
		soundSelection += 1;
		current = nil; menuOpen = false;
		ST.Name = "Off"; M.Preset = "Off";
		NeverLose.OnToggleChanged = function() end;
		onSound:Destroy(); offSound:Destroy(); holder:Destroy();
	end;
end);

guard("music", function()
	local HttpService = game:GetService("HttpService");
	local TweenService = game:GetService("TweenService");
	local UserInputService = game:GetService("UserInputService");

	local TH = NeverLose.Lib.theme;

	local CONFIG = userFile("spotify.json");
	local AUTH = "https://accounts.spotify.com/authorize";
	local TOKEN = "https://accounts.spotify.com/api/token";
	local API = "https://api.spotify.com/v1";
	local REDIRECT = "http://127.0.0.1:8888/callback";
	local SCOPES = "user-read-playback-state user-modify-playback-state user-read-currently-playing";

	local Playback = {
		title = "Nothing playing",
		artist = "",
		artwork = "",
		duration = 0,
		position = 0,
		playing = false,
		volume = 50,
		canSeek = false,
		canSkipNext = false,
		canSkipPrevious = false,
		shuffle = false,
		loop = false,
		status = "",
	};

	local HUD = {
		On = false,
		Layout = "Full",
		Artwork = true,
		Controls = true,
		Progress = true,
		Times = true,
		Visualizer = true,
		Opacity = 100,
		Scale = 100,
		Lyrics = false,
		LyricsSize = 150,
		LyricsSpot = "Bottom Left",
		LyricsX = 0,
		LyricsY = 0,
		LyricsPlaced = false,
		Spot = "Bottom Left",
		OffsetX = 0,
		OffsetY = 0,
		AccentColor = Color3.fromRGB(120, 200, 255),
		CoverSize = 52,
	};

	ESP.Music = { Playback = Playback, Hud = HUD };

	local requestFn = (syn and syn.request) or (http and http.request)
		or rawget(GLOBAL, "http_request") or rawget(GLOBAL, "request");

	local function httpJson(method, url, headers, body)
		if type(requestFn) ~= "function" then return nil, 0 end;

		local ok, res = Remote.invoke(function() return requestFn({
			Url = url,
			Method = method,
			Headers = headers,
			Body = body,
			Timeout = 12,
		}) end, 12);

		if not ok or type(res) ~= "table" then return nil, 0 end;

		local code = tonumber(res.StatusCode or res.Status or 0) or 0;

		if type(res.Body) ~= "string" or res.Body == "" then return nil, code, res end;

		local decoded;

		pcall(function() decoded = HttpService:JSONDecode(res.Body) end);

		return decoded, code, res;
	end;

	local function urlencode(value)
		return (string.gsub(tostring(value), "[^%w%-%._~]", function(c)
			return string.format("%%%02X", string.byte(c));
		end));
	end;

	local function form(pairsTable)
		local parts = {};

		for key, value in pairs(pairsTable) do
			parts[#parts + 1] = key .. "=" .. urlencode(value);
		end;

		return table.concat(parts, "&");
	end;

	local SAFE = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~";

	local function verifier()
		local out = {};

		for index = 1, 64 do
			local pick = math.random(1, #SAFE);

			out[index] = string.sub(SAFE, pick, pick);
		end;

		return table.concat(out);
	end;

	local function challengeFor(text)
		local crypt = rawget(GLOBAL, "crypt");

		if not (crypt and crypt.hash and crypt.base64encode) then return nil end;

		local ok, hex = pcall(crypt.hash, text, "sha256");
		if not ok or type(hex) ~= "string" or #hex ~= 64 or hex:find("[^%x]") then return nil end;

		local raw = (string.gsub(hex, "%x%x", function(byte)
			return string.char(tonumber(byte, 16));
		end));

		local fine, encoded = pcall(crypt.base64encode, raw);
		if not fine or type(encoded) ~= "string" then return nil end;

		encoded = string.gsub(encoded, "%+", "-");
		encoded = string.gsub(encoded, "/", "_");
		encoded = string.gsub(encoded, "=", "");

		return encoded;
	end;

	local covers, coverBusy, coverRetryAfter = {}, {}, {};

	local function coverFor(url)
		if type(url) ~= "string" or url == "" then return "" end;
		if not string.find(url, "^https?://") then return url end;

		local hit = covers[url];

		if hit then return hit end;
		if coverBusy[url] or (coverRetryAfter[url] or 0) > os.clock() then return "" end;

		coverBusy[url] = true;

		task.spawn(function()
			local ok, asset = pcall(function()
				local body = Remote.download(url);
				if type(body) ~= "string" or #body < 32 or #body > 8 * 1024 * 1024 then return nil end;
				local image = body:sub(1, 8) == "\137PNG\13\10\26\10" or body:sub(1, 3) == "\255\216\255"
					or body:sub(1, 3) == "GIF" or (body:sub(1, 4) == "RIFF" and body:sub(9, 12) == "WEBP");
				if not image then return nil end;
				return Remote.volatile("external-cover/" .. Remote.slug(url) .. ".png", body);
			end);
			if Remote.current() and ok and type(asset) == "string" and asset ~= "" then covers[url] = asset
			else coverRetryAfter[url] = os.clock() + 15 end;
			coverBusy[url] = nil;
		end);

		return "";
	end;

	local LocalProvider = { name = "Local" };

	do
		local sound = Instance.new("Sound");
		sound:SetAttribute("VisualsOwned", true);
		sound.Name = NeverLose.RandomString();
		sound.Volume = 0.5;
		sound.Looped = false;
		sound.Parent = NeverLose.ScreenGui;

		local queue, cursor = {}, 0;
		local cover = "";

		LocalProvider.sound = sound;

		local function load(index)
			if #queue == 0 then return end;

			cursor = ((index - 1) % #queue) + 1;

			local entry = queue[cursor];

			sound.SoundId = "rbxassetid://" .. tostring(entry.id);
			sound.TimePosition = 0;
			sound:Play();
		end;

		function LocalProvider.add(text)
			local raw = tostring(text or "");
			local id = string.match(raw, "(%d+)");

			if not id then return false end;

			local rest = string.match(raw, "^%s*%d+%s*(.-)%s*$") or "";
			local artist, title = string.match(rest, "^(.-)%s*%-%s*(.+)$");

			queue[#queue + 1] = {
				id = id,
				title = title or (rest ~= "" and rest) or ("Track " .. id),
				artist = title and artist or nil,
			};

			if #queue == 1 then load(1) end;

			return true;
		end;

		function LocalProvider.clear()
			sound:Stop();

			table.clear(queue);

			cursor = 0;
		end;

		function LocalProvider.dump()
			local out = {};

			for _, entry in ipairs(queue) do
				out[#out + 1] = entry.id .. (entry.artist and (" " .. entry.artist .. " - " .. entry.title)
					or (entry.title and (" " .. entry.title) or ""));
			end;

			return out;
		end;

		function LocalProvider.restore(list)
			if type(list) ~= "table" then return end;

			LocalProvider.clear();

			for _, text in ipairs(list) do
				if type(text) == "string" then LocalProvider.add(text) end;
			end;

			sound:Stop();
			sound.TimePosition = 0;
		end;

		function LocalProvider.setCover(url) cover = url or "" end;

		function LocalProvider.play() if sound.SoundId ~= "" then sound:Resume() end end;
		function LocalProvider.pause() sound:Pause() end;
		function LocalProvider.stop() sound:Stop(); sound.TimePosition = 0 end;
		function LocalProvider.replay() sound.TimePosition = 0; sound:Play() end;
		function LocalProvider.next() if #queue > 0 then load(cursor + 1) end end;
		function LocalProvider.previous() if #queue > 0 then load(cursor - 1) end end;
		function LocalProvider.setLoop(v) sound.Looped = v and true or false end;
		function LocalProvider.setVolume(v) sound.Volume = math.clamp(v, 0, 100) / 100 end;
		function LocalProvider.seek(fraction)
			if sound.TimeLength > 0 then sound.TimePosition = sound.TimeLength * math.clamp(fraction, 0, 1) end;
		end;

		function LocalProvider.read(into)
			local entry = queue[cursor];

			into.title = entry and entry.title or "No track queued";
			into.artist = (entry and entry.artist)
				or ((#queue > 0) and (cursor .. " / " .. #queue) or "");
			into.album = "";
			into.artwork = cover;
			into.duration = sound.TimeLength or 0;
			into.position = sound.TimePosition or 0;
			into.playing = sound.IsPlaying;
			into.volume = math.floor(sound.Volume * 100 + 0.5);
			into.canSeek = sound.TimeLength > 0;
			into.canSkipNext = #queue > 1;
			into.canSkipPrevious = #queue > 1;
			into.loop = sound.Looped;
			into.status = "";
		end;

		onUnload("music local", function()
			pcall(function() sound:Stop() end);
			pcall(function() sound:Destroy() end);
		end);
	end;

	local Spotify = { name = "Spotify", connected = false };

	do
		local clientId = "";
		local refreshToken = "";
		local pendingVerifier = nil;
		local access, expires = "", 0;
		local backoffUntil = 0;

		local function save()
			if not writefile then return end;

			pcall(function()
				writefile(CONFIG, HttpService:JSONEncode({
					clientId = clientId,
					refreshToken = refreshToken,
					verifier = pendingVerifier or "",
				}));
			end);
		end;

		local function load()
			if not (isfile and readfile and isfile(CONFIG)) then return end;

			pcall(function()
				local blob = HttpService:JSONDecode(readfile(CONFIG));

				clientId = blob.clientId or "";
				refreshToken = blob.refreshToken or "";
				pendingVerifier = (blob.verifier ~= "" and blob.verifier) or nil;
			end);
		end;

		load();

		function Spotify.setClientId(value)
			clientId = tostring(value or ""):gsub("%s", "");

			save();
		end;

		function Spotify.hasClientId() return clientId ~= "" end;

		local function refresh()
			if clientId == "" or refreshToken == "" then return false end;

			local body, code = httpJson("POST", TOKEN,
				{ ["Content-Type"] = "application/x-www-form-urlencoded" },
				form({
					grant_type = "refresh_token",
					refresh_token = refreshToken,
					client_id = clientId,
				}));

			if code == 200 and body and body.access_token then
				access = body.access_token;
				expires = os.clock() + (tonumber(body.expires_in) or 3600) - 60;

				if body.refresh_token then refreshToken = body.refresh_token; save() end;

				Spotify.connected = true;

				return true;
			end;

			if code == 400 or code == 401 then
				refreshToken = "";
				Spotify.connected = false;

				save();
			end;

			return false;
		end;

		local function token()
			if access ~= "" and os.clock() < expires then return access end;

			return refresh() and access or nil;
		end;

		function Spotify.begin()
			if clientId == "" then
				Notification.new({ Title = "Spotify", Content = "Set a Client ID first", Duration = 6 });

				return;
			end;

			pendingVerifier = verifier();

			save();

			local challenge = challengeFor(pendingVerifier);

			if not challenge then
				Notification.new({ Title = "Spotify", Content = "Executor has no sha256", Duration = 6 });

				return;
			end;

			local url = AUTH .. "?" .. form({
				client_id = clientId,
				response_type = "code",
				redirect_uri = REDIRECT,
				code_challenge_method = "S256",
				code_challenge = challenge,
				scope = SCOPES,
			});

			pcall(setclipboard, url);

			Notification.new({
				Title = "Spotify",
				Content = "Link copied",
				Duration = 10,
			});
		end;

		function Spotify.finish(code)
			local text = tostring(code or "");

			local value = string.match(text, "code=([^&%s]+)") or string.match(text, "^%s*(%S+)%s*$");

			if not value then
				Spotify.lastError = "No code found";

				Notification.new({ Title = "Spotify", Content = Spotify.lastError, Duration = 6 });

				return;
			end;

			if not pendingVerifier then
				Spotify.lastError = "Press Connect first";

				Notification.new({ Title = "Spotify", Content = Spotify.lastError, Duration = 7 });

				return;
			end;

			local body, status = httpJson("POST", TOKEN,
				{ ["Content-Type"] = "application/x-www-form-urlencoded" },
				form({
					grant_type = "authorization_code",
					code = value,
					redirect_uri = REDIRECT,
					client_id = clientId,
					code_verifier = pendingVerifier,
				}));

			pendingVerifier = nil;

			save();

			if status == 200 and body and body.access_token then
				access = body.access_token;
				expires = os.clock() + (tonumber(body.expires_in) or 3600) - 60;
				refreshToken = body.refresh_token or "";
				Spotify.connected = true;

				save();

				Notification.new({ Title = "Spotify", Content = "Connected", Duration = 5 });
			else
				Spotify.connected = false;
				Spotify.lastError = ("http %s: %s"):format(
					tostring(status),
					(body and (body.error_description or body.error)) or "No response"
				);

				Notification.new({
					Title = "Spotify",
					Content = Spotify.lastError,
					Duration = 8,
				});
			end;
		end;

		function Spotify.disconnect()
			access, refreshToken, expires = "", "", 0;
			Spotify.connected = false;

			save();
		end;

		local function call(method, path, body)
			local key = token();

			if not key then return nil, 401 end;

			local headers = { ["Authorization"] = "Bearer " .. key };

			if body then headers["Content-Type"] = "application/json" end;

			return httpJson(method, API .. path, headers, body);
		end;

		Spotify.call = call;

		function Spotify.play() call("PUT", "/me/player/play") end;
		function Spotify.pause() call("PUT", "/me/player/pause") end;
		function Spotify.next() call("POST", "/me/player/next") end;
		function Spotify.previous() call("POST", "/me/player/previous") end;
		function Spotify.setVolume(v) call("PUT", "/me/player/volume?volume_percent=" .. math.floor(math.clamp(v, 0, 100))) end;
		function Spotify.seek(fraction)
			if Playback.duration <= 0 then return end;

			call("PUT", "/me/player/seek?position_ms=" .. math.floor(Playback.duration * math.clamp(fraction, 0, 1) * 1000));
		end;
		function Spotify.stop() Spotify.pause() end;
		function Spotify.replay() Spotify.seek(0) end;
		function Spotify.setLoop(v) call("PUT", "/me/player/repeat?state=" .. (v and "track" or "off")) end;

		function Spotify.refreshState(into)
			if clientId == "" then
				into.status = "No Client ID";
				into.title = "Spotify not set up";
				into.artist = "";
				into.playing = false;

				return;
			end;

			if refreshToken == "" and access == "" then
				into.status = "not connected";
				into.title = "Spotify not connected";
				into.artist = "";
				into.playing = false;

				return;
			end;

			if os.clock() < backoffUntil then return end;

			local body, code, raw = call("GET", "/me/player");

			if code == 204 then
				into.status = "No active device";
				into.title = "Nothing playing";
				into.artist = "open Spotify on any device";
				into.artwork = "";
				into.playing = false;
				into.duration, into.position = 0, 0;

				return;
			end;

			if code == 429 then
				local wait = 5;

				if raw and raw.Headers then
					wait = tonumber(raw.Headers["retry-after"] or raw.Headers["Retry-After"]) or 5;
				end;

				backoffUntil = os.clock() + wait;
				into.status = "rate limited";

				return;
			end;

			if code == 401 then
				if refresh() then return end;

				into.status = "session expired";
				into.playing = false;

				return;
			end;

			if code == 403 then
				local reason = raw and type(raw.Body) == "string" and raw.Body or "";

				if string.find(reason, "premium", 1, true) or string.find(reason, "Premium", 1, true) then
					into.status = "needs Spotify Premium on the app owner";
					into.title = "Spotify unavailable";
				elseif reason ~= "" then
					into.status = string.sub(reason, 1, 90);
					into.title = "Spotify unavailable";
				else
					into.status = "private session";
				end;

				into.artist = "";
				into.artwork = "";
				into.playing = false;
				into.duration, into.position = 0, 0;

				return;
			end;

			if not body or type(body.item) ~= "table" then
				into.title, into.artist, into.album, into.artwork = "Nothing playing", "", "", "";
				into.duration, into.position = 0, 0;
				into.canSeek, into.canSkipNext, into.canSkipPrevious, into.loop, into.shuffle = false, false, false, false, false;
				into.status = (code == 200) and "Nothing playing" or ("http " .. tostring(code));
				into.playing = body and body.is_playing or false;

				return;
			end;

			local item = body.item;
			local artists = {};

			for _, artist in ipairs(item.artists or {}) do artists[#artists + 1] = artist.name end;

			local art = "";

			if item.album and type(item.album.images) == "table" then

				local best;

				for _, image in ipairs(item.album.images) do
					if not best or (image.width and image.width >= 160 and image.width < (best.width or 1e9)) then
						best = image;
					end;
				end;

				art = (best and best.url) or (item.album.images[1] and item.album.images[1].url) or "";
			end;

			into.trackId = item.id;
			into.album = (item.album and item.album.name) or "";
			into.title = item.name or "Unknown";
			into.artist = table.concat(artists, ", ");
			into.artwork = art;
			into.duration = (tonumber(item.duration_ms) or 0) / 1000;
			into.position = (tonumber(body.progress_ms) or 0) / 1000;
			into.playing = body.is_playing and true or false;
			into.shuffle = body.shuffle_state and true or false;
			into.loop = (body.repeat_state or "off") ~= "off";
			into.canSeek = true;
			into.canSkipNext = true;
			into.canSkipPrevious = true;
			into.status = "";

			if body.device and body.device.volume_percent then
				into.volume = body.device.volume_percent;
			end;
		end;
	end;

	local audioCache = {};
	local audioBytes = 0;

	local function cacheAudio(url)
		if type(url) ~= "string" or url == "" then return nil, "no url" end;

		if audioCache[url] then return audioCache[url] end;

		if type(writefile) ~= "function" or type(Remote.custom) ~= "function" then
			return nil, "executor cannot write files";
		end;

		local stamp;

		pcall(function()
			local hasher = rawget(GLOBAL, "crypt");

			stamp = (hasher and hasher.hash) and string.sub(hasher.hash(url, "sha256"), 1, 24) or nil;
		end);

		stamp = stamp or Remote.slug(url);

		local kind = string.match(string.lower(url):match("^[^?#]+") or "", "%.(%a+)$") or "mp3";

		if kind ~= "mp3" and kind ~= "ogg" and kind ~= "wav" then kind = "mp3" end;

		if not url:match("^https?://") then return nil, "unsupported audio URL" end;
		local bytes = Remote.download(url);
		if type(bytes) ~= "string" or #bytes <= 4096 then return nil, "download failed" end;
		local header = bytes:sub(1, 12);
		local first, second = bytes:byte(1, 2);
		local audio = header:sub(1, 4) == "OggS" or (header:sub(1, 4) == "RIFF" and header:sub(9, 12) == "WAVE")
			or header:sub(1, 3) == "ID3" or (first == 255 and second and bit32.band(second, 224) == 224);
		if not Remote.current() or not audio or #bytes > 32 * 1024 * 1024 then return nil, "invalid audio response" end;
		if audioBytes + #bytes > 128 * 1024 * 1024 then return nil, "audio cache limit reached" end;
		local asset = Remote.volatile("external-audio/" .. stamp .. "." .. kind, bytes);
		if type(asset) ~= "string" or asset == "" then return nil, "asset failed" end;
		audioBytes += #bytes;

		audioCache[url] = asset;

		return asset;
	end;

	local function streamProvider(name, resolve)
		local P = { name = name };
		local active, selected, epoch, sequence = true, false, 0, 0;

		local sound = Instance.new("Sound");
		sound:SetAttribute("VisualsOwned", true);
		sound.Name = NeverLose.RandomString();
		sound.Volume = 0.5;
		sound.Looped = false;
		sound.Parent = NeverLose.ScreenGui;

		local queue, cursor, note = {}, 0, "";

		P.sound = sound;

		local function load(index, revision)
			if #queue == 0 or not ALIVE or not active or not selected or (revision and revision ~= epoch) then return end;
			sequence += 1;
			local mine, revision = sequence, epoch;

			cursor = ((index - 1) % #queue) + 1;

			local entry = queue[cursor];

			if not entry.asset then
				note = "loading " .. tostring(entry.title);

				local asset, why = cacheAudio(entry.url);
				if not ALIVE or not active or not selected or epoch ~= revision or sequence ~= mine or not sound.Parent then return end;

				if not asset then
					note = tostring(why);

					return;
				end;

				entry.asset = asset;
			end;

			note = "";
			sound.SoundId = entry.asset;
			sound.TimePosition = 0;
			sound:Play();
		end;

		function P.add(text)
			local revision = epoch;
			task.spawn(function()
				if not ALIVE or not active or revision ~= epoch then return end;
				note = "resolving...";

				local ok, track, why = pcall(resolve, text);
				if not ALIVE or not active or revision ~= epoch then return end;

				if not ok then
					note = tostring(track);

					return;
				end;

				if not track then
					note = tostring(why or "Nothing found");

					return;
				end;

				local list = track.tracks or { track };

				for _, one in ipairs(list) do
					if type(one.url) == "string" and one.url ~= "" then
						queue[#queue + 1] = {
							title = one.title or "Unknown",
							artist = one.artist or "",
							artwork = one.artwork or "",
							duration = tonumber(one.duration) or 0,
							url = one.url,
						};
					end;
				end;

				note = "";

				if cursor == 0 and #queue > 0 then load(1) end;
			end);

			return true;
		end;

		function P.clear()
			epoch += 1; sequence += 1;
			sound:Stop();
			sound.SoundId = "";
			table.clear(queue);
			cursor, note = 0, "";
		end;

		function P.activate() selected = true end;
		function P.play() if selected and sound.SoundId ~= "" then sound:Resume() elseif selected and #queue > 0 then task.spawn(load, math.max(1, cursor), epoch) end end;
		function P.pause() sound:Pause() end;
		function P.stop() epoch += 1; sequence += 1; sound:Stop(); sound.TimePosition = 0 end;
		function P.deactivate() selected = false; epoch += 1; sequence += 1; sound:Pause() end;
		function P.replay() if selected then sound.TimePosition = 0; sound:Play() end end;
		function P.next() if selected and #queue > 0 then task.spawn(load, cursor + 1, epoch) end end;
		function P.previous() if selected and #queue > 0 then task.spawn(load, cursor - 1, epoch) end end;
		function P.setLoop(v) sound.Looped = v and true or false end;
		function P.setVolume(v) sound.Volume = math.clamp(v, 0, 100) / 100 end;

		function P.seek(fraction)
			if sound.TimeLength > 0 then
				sound.TimePosition = sound.TimeLength * math.clamp(fraction, 0, 1);
			end;
		end;

		function P.read(into)
			local entry = queue[cursor];

			into.title = entry and entry.title or (name .. ": nothing queued");
			into.artist = entry and entry.artist or "";
			into.album = "";
			into.artwork = entry and coverFor(entry.artwork) or "";
			into.duration = (sound.TimeLength > 0) and sound.TimeLength or (entry and entry.duration or 0);
			into.position = sound.TimePosition or 0;
			into.playing = sound.IsPlaying;
			into.volume = math.floor(sound.Volume * 100 + 0.5);
			into.canSeek = sound.TimeLength > 0;
			into.canSkipNext = #queue > 1;
			into.canSkipPrevious = #queue > 1;
			into.loop = sound.Looped;
			into.status = note;
		end;

		onUnload("music " .. string.lower(name), function()
			active = false; epoch += 1; sequence += 1; table.clear(queue);
			pcall(function() sound:Stop() end);
			pcall(function() sound:Destroy() end);
		end);

		return P;
	end;

	local SC = { Client = "" };

	local function soundcloudResolve(text)
		local raw = string.match(tostring(text or ""), "^%s*(.-)%s*$");

		if raw == "" then return nil, "paste a soundcloud link" end;

		if string.find(string.lower(raw), "%.mp3") or string.find(string.lower(raw), "%.ogg") then
			return { title = string.match(raw, "([^/]+)%.%a+") or "Track", artist = "", url = raw };
		end;

		if SC.Client == "" then return nil, "set a client id first" end;

		local data, code = httpJson("GET", ("https://api-v2.soundcloud.com/resolve?url=%s&client_id=%s")
			:format(urlencode(raw), urlencode(SC.Client)));

		if code == 401 or code == 403 then return nil, "client id rejected" end;
		if type(data) ~= "table" then return nil, "resolve failed (" .. tostring(code) .. ")" end;

		local items = data.tracks or { data };
		local out = {};

		for _, item in ipairs(items) do
			if type(item) == "table" and type(item.media) == "table" then
				local stream;

				for _, t in ipairs(item.media.transcodings or {}) do
					if type(t) == "table" and type(t.format) == "table"
						and t.format.protocol == "progressive" then
						stream = t.url;
					end;
				end;

				if stream then
					local hand, leadCode = httpJson("GET", stream .. "?client_id=" .. urlencode(SC.Client));

					if type(hand) == "table" and type(hand.url) == "string" then
						out[#out + 1] = {
							title = item.title or "Track",
							artist = (type(item.user) == "table" and item.user.username) or "",
							artwork = item.artwork_url or "",
							duration = (tonumber(item.duration) or 0) / 1000,
							url = hand.url,
						};
					elseif leadCode == 401 or leadCode == 403 then
						return nil, "client id rejected";
					end;
				end;
			end;
		end;

		if #out == 0 then return nil, "No playable stream" end;

		return { tracks = out };
	end;

	local VK = { Token = "" };

	local function vkResolve(text)
		local raw = string.match(tostring(text or ""), "^%s*(.-)%s*$");

		if string.find(string.lower(raw), "%.mp3") or string.find(string.lower(raw), "%.m4a") then
			return { title = string.match(raw, "([^/]+)%.%a+") or "Track", artist = "", url = raw };
		end;

		if VK.Token == "" then return nil, "set a vk token first" end;

		local owner, count = string.match(raw, "^(-?%d+)"), 25;
		local url = ("https://api.vk.com/method/audio.get?v=5.131&count=%d&access_token=%s")
			:format(count, urlencode(VK.Token));

		if owner then url = url .. "&owner_id=" .. owner end;

		local data, code = httpJson("GET", url);

		if type(data) ~= "table" then return nil, "vk unreachable (" .. tostring(code) .. ")" end;

		if type(data.error) == "table" then
			return nil, "vk: " .. tostring(data.error.error_msg or data.error.error_code);
		end;

		local items = (type(data.response) == "table" and data.response.items) or {};
		local out = {};

		for _, item in ipairs(items) do

			if type(item) == "table" and type(item.url) == "string" and item.url ~= ""
				and not string.find(item.url, "%.m3u8") then
				out[#out + 1] = {
					title = item.title or "Track",
					artist = item.artist or "",
					duration = tonumber(item.duration) or 0,
					url = item.url,
				};
			end;
		end;

		if #out == 0 then return nil, "No direct file" end;

		return { tracks = out };
	end;

	local SoundCloud = streamProvider("SoundCloud", soundcloudResolve);
	local Vk = streamProvider("VK", vkResolve);

	ESP.Music.SoundCloud = SoundCloud;
	ESP.Music.Vk = Vk;

	local providers = { Local = LocalProvider, Spotify = Spotify, SoundCloud = SoundCloud, VK = Vk };
	local current = "Local";
	local providerEpoch = 0;
	local musicSettings = {volume=50, loop=false};

	ESP.Music.Providers = providers;
	ESP.Music.Local = LocalProvider;
	ESP.Music.Spotify = Spotify;

	local function provider() return providers[current] or LocalProvider end;

	local function command(name, ...)
		local p = provider();
		local fn = p[name];

		if type(fn) == "function" then pcall(fn, ...) end;
	end;

	local gui = Render.gui("music", 40);

	local panel = Instance.new("Frame");
